(window.STORIES=window.STORIES||[]).push(
{"id": 1001, "siri": "Sirah-01", "no": 1, "nama": "Abu Bakar As-Siddiq", "tajuk": "Saidina Abu Bakar As-Siddiq RA — Detik Cemas Di Gua Thawr", "lokasi": "Safar Tahun 14 Kenabian (September 622 M) | Fasa Hijrah Makkah ke Madinah", "ibrah": "Tawakal, Persahabatan Sejati & Ketenangan Krisis", "sumber": "Sahih Al-Bukhari 3653", "link": "https://sunnah.com/bukhari:3653", "tema": "Sabar & Tawakal", "hook": "\"Wahai Rasulullah, kalau salah seorang daripada mereka pandang ke bawah kaki mereka sahaja, pasti mereka akan nampak kita!\"", "body": ["Suara bisikan itu bergetar menahan cemas.", "Di luar mulut Gua Thawr, derapan tapak kaki pemuda-pemuda Quraisy jelas kedengaran.", "Pedang mereka terhunus tajam.", "Tawaran 100 ekor unta merah menjadikan seluruh Makkah gelap mata memburu dua insan di dalam gua sempit itu.", "Insan yang berbisik penuh bimbang itu ialah Saidina Abu Bakar As-Siddiq RA.", "Beliau bukan takutkan kematian dirinya sendiri.", "Beliau takut jika sesuatu menimpa kekasih Allah, Nabi Muhammad S.A.W.", "Tiga malam mereka bersembunyi di puncak gunung batu yang curam itu.", "Sebelum Rasulullah S.A.W. melangkah masuk ke dalam gua, Abu Bakar RA terlebih dahulu masuk memeriksa setiap penjuru gelap.", "Beliau mengoyakkan pakaiannya untuk menyumbat lubang-lubang kecil agar tiada ular atau kala jengking menyengat tubuh mulia Baginda.", "Apabila musuh berdiri betul-betul di birai mulut gua, jantung Abu Bakar RA berdegup kencang.", "Jarak antara hidup dan mati ketika itu hanyalah seinci pandang.", "Namun, Rasulullah S.A.W. memandang wajah sahabat karibnya itu dengan penuh ketenangan.", "Baginda bersabda dengan satu ayat yang terpahat abadi di dalam Al-Quran:", "\"Wahai Abu Bakar! Apakah sangkaanmu terhadap dua orang, sedangkan Allah adalah yang ketiganya? Janganlah engkau bersedih, sesungguhnya Allah bersama kita.\"", "Seketika itu juga, ketenangan turun menyelimuti hati Abu Bakar RA.", "Para pemburu Quraisy berpaling pergi tanpa menyedari kelibat mereka di bawah tapak kaki sendiri.", "3 Pengajaran (Ibrah) Untuk Kita:", "Tawakal Selepas Usaha Maksimum: Rasulullah S.A.W. dan Abu Bakar RA merancang strategi rapi dengan bersembunyi di Gua Thawr ke arah selatan, kemudian menyerahkan natijah sepenuhnya kepada perlindungan Allah SWT.", "Sahabat Sejati Waktu Sempit: Sahabat sebenar bukan sekadar hadir ketika kita diraikan, tetapi sanggup mempertaruhkan keselesaan dan nyawa ketika kita diuji hebat.", "Ketenangan Pemimpin Menguatkan Pasukan: Ketika orang bawahan atau rakan seperjuangan dilanda panik, ketenangan dan keyakinan seorang pemimpin mampu memulihkan semangat seluruh pasukan.", "Sudahkah kita menghargai sahabat yang sentiasa mengingatkan kita kepada Allah ketika kita hampir berputus asa?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1002, "siri": "Sirah-01", "no": 2, "nama": "Abu Bakar As-Siddiq", "tajuk": "Saidina Abu Bakar As-Siddiq RA — Perlumbaan Infaq Perang Tabuk", "lokasi": "Rejab 9 Hijrah (Oktober 630 M) | Fasa Madinah (Persiapan Perang Tabuk)", "ibrah": "Persaingan Sihat, Keikhlasan & Keyakinan Rezeki", "sumber": "Jami' At-Tirmidhi 3675", "link": "https://sunnah.com/tirmidhi:3675", "tema": "Infaq & Harta", "hook": "\"Hari ini aku pasti akan berjaya mendahului Abu Bakar!\"", "body": ["Begitulah nekad Saidina Umar bin Al-Khattab RA di dalam hatinya.", "Ketika itu, Madinah sedang berdepan ujian getir persiapan Perang Tabuk menentang kuasa besar Rom.", "Cuaca panas membahang, musim kemarau melanda, dan perjalanan merentas padang pasir amat jauh.", "Rasulullah S.A.W. menyeru para sahabat untuk menginfaqkan harta demi melengkapkan keperluan tentera Islam.", "Kebetulan pada waktu itu, Umar RA mempunyai harta yang banyak.", "Beliau pulang ke rumah, membahagikan seluruh kekayaannya tepat kepada dua bahagian.", "Separuh disimpan untuk keluarganya, dan separuh lagi dibawa terus ke hadapan Rasulullah S.A.W.", "Baginda bertanya, \"Wahai Umar, apakah yang engkau tinggalkan buat ahli keluargamu?\"", "Umar RA menjawab dengan yakin, \"Aku tinggalkan buat mereka jumlah yang sama banyaknya dengan apa yang aku bawa ini.\"", "Tidak lama kemudian, tiba pula Saidina Abu Bakar As-Siddiq RA membawa bungkusan hartanya.", "Rasulullah S.A.W. mengemukakan soalan yang sama:", "\"Wahai Abu Bakar, apakah yang engkau tinggalkan buat ahli keluargamu di rumah?\"", "Dengan wajah yang tenang, Abu Bakar RA menjawab:", "\"Aku tinggalkan buat mereka Allah dan Rasul-Nya.\"", "Rupa-rupanya, Abu Bakar RA telah membawa kesemua 100% harta simpanan yang ada di rumahnya tanpa meninggalkan walau satu dirham pun.", "Umar RA yang mendengar jawapan itu terus tertunduk insaf lalu berkata:", "\"Demi Allah, aku tidak akan mampu menandingi Abu Bakar dalam perlumbaan amal kebaikan buat selama-lamanya!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Berlumba Dalam Kebaikan Tanpa Hasad: Para sahabat bersaing rapat untuk menjadi penyumbang terbesar kepada agama tanpa sedikit pun rasa dengki apabila rakan mereka lebih ke hadapan.", "Kualiti Iman Menentukan Tahap Pengorbanan: Abu Bakar RA mampu menyerahkan seluruh hartanya kerana beliau seorang usahawan berpengalaman yang memiliki tawakal mutlak dan keluarga yang sama-sama reda.", "Bertindak Segera Apabila Peluang Pahala Terbuka: Jangan bertangguh apabila hadir peluang membantu agama dan masyarakat, kerana masa terbaik untuk beramal adalah ketika tenaga dan harta masih di tangan.", "Antara kita dengan sahabat baik kita hari ini, adakah kita saling mengajak ke arah kebaikan dan sedekah?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1003, "siri": "Sirah-01", "no": 3, "nama": "Abu Bakar As-Siddiq", "tajuk": "Saidina Abu Bakar As-Siddiq RA — Memuntahkan Makanan Syubhah", "lokasi": "Fasa Madinah | Kehidupan Harian & Wara' Saidina Abu Bakar RA", "ibrah": "Integriti Rezeki Halal, Audit Pendapatan & Taqwa", "sumber": "Sahih Al-Bukhari 3842", "link": "https://sunnah.com/bukhari:3842", "tema": "Akhlak & Adab", "hook": "Hanya kerana tertelan satu suap makanan yang meragukan, beliau sanggup menjolok kerongkongnya sendiri sehingga muntah!", "body": ["Kisah benar yang menggerunkan hati ini direkodkan secara sahih di dalam kitab Sahih Al-Bukhari.", "Saidina Abu Bakar As-Siddiq RA mempunyai seorang pembantu yang bekerja dan menyerahkan sebahagian hasil pendapatannya kepada beliau.", "Kebiasaannya, Abu Bakar RA amat teliti.", "Beliau sentiasa bertanya terlebih dahulu dari manakah punca makanan atau pendapatan tersebut sebelum menjamahnya.", "Namun pada suatu hari, pembantunya membawa sejenis makanan ketika Abu Bakar RA sedang lapar.", "Beliau terus mengambil satu suap dan menelannya sebelum sempat bertanya.", "Melihat hal itu, pembantunya menegur, \"Wahai tuanku, mengapa hari ini engkau tidak bertanya seperti biasa dari mana datangnya makanan ini?\"", "Abu Bakar RA tersentak lalu bertanya, \"Apakah sebenarnya punca makanan ini?\"", "Pembantunya menjelaskan:", "\"Dahulu pada zaman Jahiliyah, aku pernah berpura-pura menjadi tukang tilik nasib untuk seorang lelaki padahal aku tidak tahu menilik. Hari ini aku terserempak dengannya, lalu dia memberikan upah atas tilikan palsu dahulu. Makanan yang engkau makan tadi dibeli daripada hasil wang tersebut.\"", "Sebaik mendengar pengakuan itu, wajah Abu Bakar RA berubah pucat!", "Tanpa berlengah sesaat pun, beliau terus memasukkan jarinya ke dalam mulut dan memaksa dirinya memuntahkan semula segala isi perutnya.", "Beliau memuntahkan makanan itu sehingga habis kerana takut walau secebis rezeki haram menjadi darah dagingnya.", "3 Pengajaran (Ibrah) Untuk Kita:", "Tegas Menjaga Kesucian Rezeki: Biarpun hanya satu suap atau nilai yang kecil, sumber yang haram dan hasil penipuan tetap wajib dijauhi sepenuhnya.", "Audit Punca Pendapatan Harian: Sebelum menerima komisen, hadiah, atau keuntungan perniagaan, pastikan urus niaga tersebut bebas daripada unsur penipuan, riba, dan kezaliman.", "Makanan Halal Membentuk Hati Yang Bersih: Kelembutan hati untuk beribadah dan ketenangan jiwa dalam keluarga bermula daripada suapan rezeki yang 100% halal dan berkat.", "Sejauh manakah kita menyemak keberkatan dan status halal setiap ringgit yang masuk ke dalam akaun kita hari ini?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1004, "siri": "Sirah-01", "no": 4, "nama": "Umar bin Al-Khattab", "tajuk": "Saidina Umar bin Al-Khattab RA — Daripada Pedang Terhunus Kepada Pelindung Islam", "lokasi": "Zulhijjah Tahun 6 Kenabian (616 M) | Fasa Makkah", "ibrah": "Kuasa Hidayah, Keberanian Prinsip & Perubahan Diri", "sumber": "Sahih Al-Bukhari 3863", "link": "https://sunnah.com/bukhari:3863", "tema": "Taubat & Hidayah", "hook": "\"Kami sentiasa berada dalam kemuliaan dan kekuatan sejak Umar memeluk Islam!\"", "body": ["Itulah pengakuan jujur sahabat agung, Abdullah bin Mas'ud RA di dalam Sahih Al-Bukhari.", "Sebelum hari bersejarah itu, umat Islam di Makkah hidup dalam ketakutan dan penindasan yang amat dahsyat.", "Mereka tidak berani mendirikan solat secara terbuka di sisi Kaabah.", "Pada suatu hari di tahun keenam kenabian, Umar bin Al-Khattab keluar dari rumahnya dengan pedang terhunus.", "Matanya merah menyala dengan satu niat: mahu menamatkan riwayat Rasulullah S.A.W.", "Di pertengahan jalan, beliau diberitahu bahawa adik kandungnya sendiri, Fatimah binti Al-Khattab dan iparnya Sa'id bin Zaid RA telah pun memeluk Islam secara rahsia.", "Umar berpatah arah menerjah ke rumah adiknya dengan penuh kemarahan sehingga melukakan wajah Fatimah.", "Namun, ketegasan iman adiknya yang enggan berganjak walau setapak menyentakkan jiwa Umar.", "Apabila melihat darah mengalir di wajah adiknya sendiri, hati Umar yang keras tiba-tiba menjadi sayu.", "Beliau meminta untuk melihat lembaran wahyu Surah Taha yang sedang dibaca di rumah tersebut.", "Sebaik membaca ayat-ayat suci tentang keagungan Allah SWT, jiwa Umar bergegar hebat.", "Beliau terus melangkah ke Darul Arqam dan melafazkan syahadah di hadapan Rasulullah S.A.W.", "Sejak detik itu, Umar RA tampil di barisan hadapan memimpin umat Islam keluar berarak ke Masjidil Haram dan bersolat secara terbuka buat pertama kalinya!", "3 Pengajaran (Ibrah) Untuk Kita:", "Jangan Pernah Putus Asa Terhadap Hidayah Manusia: Insan yang paling keras menentang kebenaran hari ini boleh bertukar menjadi pembela agama paling gagah pada esok hari dengan izin Allah.", "Keberanian Mengubah Suasana: Kehadiran seorang individu yang berani berdiri di atas prinsip kebenaran mampu mengangkat maruah dan keyakinan seluruh komuniti yang tertindas.", "Ketenangan Menghadapi Kemarahan: Keteguhan Fatimah binti Al-Khattab dan Sa'id bin Zaid RA mempertahankan prinsip ketika diasak kemarahan akhirnya melembutkan hati seorang pahlawan.", "Adakah kita menggunakan kekuatan, pengaruh, dan kelebihan yang Allah kurniakan kepada kita untuk membela kebenaran?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1005, "siri": "Sirah-01", "no": 5, "nama": "Umar bin Al-Khattab", "tajuk": "Saidina Umar bin Al-Khattab RA — Syaitan Pun Mengambil Jalan Lain", "lokasi": "Fasa Madinah | Keperibadian & Wibawa Saidina Umar RA", "ibrah": "Wibawa Diri, Ketegasan Bertempat & Jati Diri", "sumber": "Sahih Al-Bukhari 3683", "link": "https://sunnah.com/bukhari:3683", "tema": "Kepimpinan & Keberanian", "hook": "Suasana di bilik Rasulullah S.A.W. yang tadinya riuh dengan suara beberapa wanita Quraisy tiba-tiba bertukar senyap sunyi!", "body": ["Kisah menarik ini diriwayatkan oleh Sa'ad bin Abi Waqqas RA di dalam Sahih Al-Bukhari.", "Beberapa orang wanita sedang duduk bertanya soalan kepada Rasulullah S.A.W. dengan suara yang agak tinggi.", "Tiba-tiba terdengar suara Saidina Umar bin Al-Khattab RA memberi salam dan meminta izin untuk masuk.", "Sebaik mendengar suara Umar RA di balik pintu, wanita-wanita tersebut bergegas bangun dan duduk dengan penuh tertib serta senyap.", "Apabila Umar RA melangkah masuk, beliau melihat Rasulullah S.A.W. sedang tersenyum lebar.", "Umar RA berkata, \"Semoga Allah sentiasa membuatkan engkau tersenyum, wahai Rasulullah!\"", "Baginda S.A.W. menjawab:", "\"Aku hairan melihat wanita-wanita di sisiku ini. Sebaik sahaja mereka mendengar suaramu meminta izin, mereka terus bergegas menutup wajah dan mendiamkan diri.\"", "Umar RA menoleh kepada mereka lalu menegur:", "\"Wahai musuh kepada diri kamu sendiri! Mengapa kamu takut kepadaku sedangkan Rasulullah S.A.W. lebih berhak untuk kamu takuti dan hormati?\"", "Mereka menjawab, \"Kerana engkau lebih keras dan tegas berbanding Rasulullah S.A.W.\"", "Mendengar perbualan itu, Rasulullah S.A.W. bersabda dengan satu pengiktirafan luar biasa:", "\"Wahai Ibn Al-Khattab! Demi Tuhan yang jiwaku berada di tangan-Nya, tidaklah syaitan bertembung denganmu di satu lorong melainkan syaitan itu pasti akan berpaling mengambil lorong yang lain!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Ketegasan Prinsip Melahirkan Wibawa: Ketegasan Umar RA bukan kerana sifat zalim, tetapi kerana keteguhan beliau menjaga adab dan hukum Allah sehingga disegani kawan mahupun lawan.", "Iman Yang Kuat Menundukkan Bisikan Syaitan: Apabila seseorang tegas menjaga batas agama dan tidak berkompromi dengan maksiat, gangguan syaitan sendiri akan menjauh daripadanya.", "Gabungan Kelembutan Dan Ketegasan Dalam Organisasi: Dalam sesebuah keluarga atau organisasi, perlu ada keseimbangan antara sifat lemah lembut yang menyantuni dan ketegasan yang mendisiplinkan.", "Bagaimanakah kita membina jati diri agar dihormati kerana prinsip dan akhlak, bukan ditakuti kerana kezaliman?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1006, "siri": "Sirah-01", "no": 6, "nama": "Umar bin Al-Khattab", "tajuk": "Saidina Umar bin Al-Khattab RA — Tangisan & Akauntabiliti Di Saat Akhir Hayat", "lokasi": "Zulhijjah 23 Hijrah (November 644 M) | Madinah Al-Munawwarah", "ibrah": "Amanah Kepimpinan, Rendah Diri & Bebas Hutang", "sumber": "Sahih Al-Bukhari 3700", "link": "https://sunnah.com/bukhari:3700", "tema": "Kepimpinan & Keberanian", "hook": "\"Demi Allah, sekiranya aku memiliki emas sepenuh isi bumi ini, nescaya aku akan gunakannya untuk menebus diriku daripada azab Allah sebelum aku bertemu dengan-Nya!\"", "body": ["Itulah rintihan seorang pemerintah empayar Islam yang paling adil ketika tubuhnya terbaring berlumuran darah selepas ditikam oleh Abu Lu'lu'ah ketika mengimami solat Subuh.", "Saidina Umar bin Al-Khattab RA telah memerintah selama 10 tahun.", "Di bawah kepimpinannya, empayar Parsi tumbang dan wilayah Syam serta Mesir dibuka.", "Namun ketika saat kematian menghampiri, Umar RA langsung tidak membanggakan kejayaan politik atau ketenteraannya.", "Seorang pemuda datang memuji beliau: \"Bergembiralah wahai Amirul Mukminin dengan berita gembira daripada Allah! Engkau telah bersahabat dengan Rasulullah S.A.W., memimpin dengan adil, dan kini gugur syahid.\"", "Tetapi apakah jawapan Umar RA di dalam Sahih Al-Bukhari?", "Beliau menjawab dengan penuh rendah diri:", "\"Aku hanya berharap agar semua urusan kepimpinanku itu sekadar impas (cukup-cukup menyelamatkan diriku), tidak menjadi beban dosa ke atasku dan tidak pula aku menuntut pahala daripadanya!\"", "Kemudian beliau memanggil anaknya, Abdullah bin Umar RA, untuk mengira berapakah baki hutang peribadinya.", "Beliau memerintahkan agar seluruh hutangnya dilunaskan terlebih dahulu daripada harta keluarganya.", "Malah, beliau meminta izin secara rasmi dengan penuh adab kepada Ummul Mukminin Saidatina Aisyah RA untuk dikebumikan di sisi sahabat tercintanya, Rasulullah S.A.W. dan Abu Bakar RA, sambil berpesan:", "\"Janganlah kamu katakan 'Amirul Mukminin meminta izin', kerana hari ini aku bukan lagi Amirul Mukminin!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Jawatan Adalah Amanah Berat, Bukan Kemuliaan: Semakin tinggi kedudukan seseorang di dunia, semakin besar rasa takut dan akauntabiliti yang perlu dirasai terhadap hisab di akhirat.", "Jangan Tertipu Dengan Pujian Manusia: Pujian orang ramai tidak boleh melalaikan kita daripada terus muhasabah kelemahan diri di hadapan Allah SWT.", "Selesaikan Urusan Hutang Dengan Teliti: Orang beriman sangat mengambil berat soal melunaskan hutang dan menjaga hak orang lain sebelum kembali menghadap Pencipta.", "Jika para sahabat yang sudah dijamin Syurga pun begitu gerun dengan hisab amanah mereka, bagaimanakah pula persediaan kita hari ini?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1007, "siri": "Sirah-01", "no": 7, "nama": "Uthman bin Affan", "tajuk": "Saidina Uthman bin Affan RA — Strategi Membeli Telaga Ruma & Wakaf Air", "lokasi": "Fasa Awal Madinah | Krisis Bekalan Air Bersih", "ibrah": "Infaq Strategik, Penyelesaian Masalah & Aset Akhirat", "sumber": "Jami' At-Tirmidhi 3703", "link": "https://sunnah.com/tirmidhi:3703", "tema": "Infaq & Harta", "hook": "Ketika seluruh penduduk Madinah berdepan kesukaran air bersih, seorang jutawan tampil membeli telaga terbaik di kota itu lalu meletakkan timbanya sama rata dengan timba orang miskin!", "body": ["Kisah kehebatan strategi kebajikan Saidina Uthman bin Affan RA ini direkodkan di dalam Sahih Al-Bukhari dan Jami' At-Tirmidhi.", "Ketika kaum Muhajirin baru berhijrah ke Madinah, bekalan air tawar yang bersih amat terhad.", "Air yang paling elok datang daripada sebuah telaga bernama Telaga Ruma.", "Namun, telaga itu dimiliki oleh seorang individu yang menjual airnya pada harga yang membebankan orang ramai.", "Melihat kesempitan umat Islam, Rasulullah S.A.W. melontarkan satu tawaran pelaburan akhirat:", "\"Sesiapa yang membeli Telaga Ruma, lalu menjadikan timbanya di dalam telaga itu sama rata bersama timba-timba umat Islam yang lain, maka baginya ganjaran yang lebih baik di dalam Syurga.\"", "Saidina Uthman bin Affan RA tidak berlengah.", "Beliau segera berunding dengan pemilik telaga tersebut dan membelinya dengan harta peribadinya yang bernilai puluhan ribu dirham.", "Sebaik sahaja Telaga Ruma sah menjadi miliknya, Uthman RA mengisytiharkan air telaga itu percuma untuk seluruh penduduk Madinah, sama ada kaya mahupun miskin!", "Yang paling menyentuh hati, walaupun Uthman RA adalah pemilik asal yang membelanjakan wang besar untuk membeli telaga tersebut, beliau tetap beratur menggunakan timba biasa seperti rakyat jelata yang lain apabila mahu mengambil air untuk kegunaan rumahnya sendiri.", "3 Pengajaran (Ibrah) Untuk Kita:", "Infaq Yang Menyelesaikan Masalah Asas Masyarakat: Sedekah dan wakaf paling berimpak tinggi adalah yang menyelesaikan keperluan kritikal orang ramai secara berpanjangan seperti bekalan air dan pendidikan.", "Kekayaan Sebagai Jambatan Ke Syurga: Di tangan orang yang beriman dan pemurah, harta kekayaan bukan punca kesombongan, sebaliknya menjadi alat paling pantas untuk meraih keredhaan Allah.", "Rendah Diri Walaupun Menjadi Penyumbang Utama: Uthman RA tidak menuntut layanan istimewa atas sumbangannya, malah meletakkan dirinya sama taraf dengan masyarakat awam.", "Apakah satu amal jariah atau wakaf yang boleh kita mulakan hari ini agar pahalanya terus mengalir selepas kita tiada?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1008, "siri": "Sirah-01", "no": 8, "nama": "Uthman bin Affan", "tajuk": "Saidina Uthman bin Affan RA — Tajaan 300 Unta & 1,000 Dinar Emas Di Tabuk", "lokasi": "Rejab 9 Hijrah (Oktober 630 M) | Persiapan Ekspedisi Perang Tabuk", "ibrah": "Memberi Ketika Sempit, Over-Deliver & Harta Bermanfaat", "sumber": "Jami' At-Tirmidhi 3700", "link": "https://sunnah.com/tirmidhi:3700", "tema": "Infaq & Harta", "hook": "\"Tidak akan memudaratkan Uthman apa sahaja yang dilakukannya selepas hari ini!\"", "body": ["Kalimah jaminan luar biasa itu diulang sebanyak dua kali oleh Rasulullah S.A.W. ketika Baginda turun dari mimbar Masjid Nabawi.", "Apakah pengorbanan yang dilakukan oleh Saidina Uthman bin Affan RA sehingga mendapat jaminan setinggi itu?", "Ketika itu umat Islam dipanggil menyertai Perang Tabuk yang digelar Jaisyul Usrah (Pasukan Kesukaran).", "Jarak perjalanan terlalu jauh, cuaca panas terik, dan bekalan tunggangan serta makanan sangat kritikal.", "Rasulullah S.A.W. berdiri di atas mimbar menyeru para sahabat untuk menaja kelengkapan tentera.", "Saidina Uthman bin Affan RA bangkit kali pertama lalu berkata:", "\"Wahai Rasulullah! Aku menanggung 100 ekor unta lengkap dengan pelana dan bekas airnya di jalan Allah!\"", "Baginda S.A.W. terus menyeru sumbangan lagi kerana jumlah tentera mencecah 30,000 orang.", "Uthman RA bangkit buat kali kedua:", "\"Wahai Rasulullah! Aku tambah lagi tanggungan menjadi 200 ekor unta lengkap dengan pelana dan bekas airnya!\"", "Baginda menyeru lagi buat kali ketiga, dan sekali lagi Uthman RA bangkit:", "\"Wahai Rasulullah! Aku tanggung 300 ekor unta lengkap dengan segala pelana dan bekas airnya di jalan Allah!\"", "Dalam riwayat lain, beliau turut membawa 1,000 keping dinar emas dan mencurahkannya ke atas pangkuan Rasulullah S.A.W.", "Para sahabat yang menyaksikan peristiwa itu melihat betapa bersinarnya wajah Baginda S.A.W. mendoakan keberkatan buat Uthman RA.", "3 Pengajaran (Ibrah) Untuk Kita:", "Memberi Lebih Daripada Yang Dijangka (Over-Deliver): Apabila melihat keperluan agama dan masyarakat masih belum mencukupi, Uthman RA terus menambah sumbangannya berulang kali tanpa berkira.", "Waktu Krisis Adalah Lubuk Pahala Terbesar: Ketika ramai orang menahan harta kerana bimbangkan kemelesetan dan kemarau, orang beriman melihat saat sukar sebagai peluang terbaik membantu sesama insan.", "Kukuhkan Ekonomi Diri Untuk Menguatkan Ummah: Keupayaan Uthman RA menaja ratusan tunggangan perang lahir daripada kecekapan beliau membina perniagaan yang kukuh dan berkat sejak muda.", "Adakah kita sedang berusaha memperkukuhkan kewangan kita dengan niat untuk menjadi penyumbang besar kepada kebaikan?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1009, "siri": "Sirah-01", "no": 9, "nama": "Uthman bin Affan", "tajuk": "Saidina Uthman bin Affan RA — Malaikat Turut Malu Kepadanya", "lokasi": "Fasa Madinah | Kemuliaan Akhlak & Sifat Haya' Saidina Uthman RA", "ibrah": "Sifat Malu (Haya'), Akhlak Mulia & Kelembutan Jiwa", "sumber": "Sahih Muslim 2401", "link": "https://sunnah.com/muslim:2401", "tema": "Akhlak & Adab", "hook": "\"Tidakkah patut aku berasa malu terhadap seorang lelaki yang para malaikat di langit sendiri berasa malu kepadanya?\"", "body": ["Kisah indah yang dirakamkan di dalam Sahih Muslim ini menyingkap satu sisi keperibadian Saidina Uthman bin Affan RA yang amat jarang dimiliki manusia.", "Pada suatu hari, Rasulullah S.A.W. sedang berehat berbaring di dalam rumah Baginda dalam keadaan sebahagian betis atau paha Baginda sedikit terbuka.", "Tidak lama kemudian, Saidina Abu Bakar As-Siddiq RA datang meminta izin untuk masuk.", "Baginda S.A.W. mengizinkan beliau masuk tanpa mengubah posisi duduknya, lalu mereka berbincang sehingga Abu Bakar RA beredar.", "Selepas itu, Saidina Umar bin Al-Khattab RA pula meminta izin untuk masuk.", "Baginda S.A.W. turut mengizinkan Umar RA masuk dalam keadaan yang sama dan berbual mesra sehingga beliau pulang.", "Namun, apabila Saidina Uthman bin Affan RA datang memberi salam dan meminta izin untuk masuk, Rasulullah S.A.W. terus bangun duduk tegak dan merapikan pakaian Baginda sepenuhnya!", "Melihat perbezaan layanan itu, Saidatina Aisyah RA bertanya selepas Uthman RA beredar:", "\"Wahai Rasulullah, mengapa ketika Abu Bakar dan Umar masuk engkau tidak bergegas merapikan pakaianmu sebagaimana engkau lakukan ketika Uthman masuk?\"", "Rasulullah S.A.W. menjawab dengan penuh kasih sayang:", "\"Sesungguhnya Uthman adalah seorang lelaki yang sangat pemalu. Aku bimbang jika aku mengizinkannya masuk dalam keadaanku tadi, dia akan berasa segan sehingga tidak dapat menyampaikan hajatnya kepadaku. Tidakkah patut aku malu kepada seorang lelaki yang malaikat sendiri berasa malu kepadanya?\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Sifat Malu (Haya') Adalah Mahkota Iman: Sifat malu untuk melakukan perkara yang kurang sopan atau melanggar adab bukanlah satu kelemahan, bahkan ia mengangkat darjat seseorang di sisi penduduk langit.", "Raikan Emosi Dan Keselesaan Tetamu: Sebagai pemimpin atau tuan rumah, kita perlu peka dengan sifat dan keperibadian orang yang berurusan dengan kita agar mereka berasa dihormati dan selesa.", "Kelembutan Peribadi Tidak Menghalang Kehebatan: Walaupun Uthman RA sangat lembut dan pemalu dalam pergaulan harian, beliau tetap tegas dan berani berada di barisan hadapan ketika agama memerlukan pengorbanan.", "Adakah kita masih memelihara sifat malu dalam percakapan, pakaian, dan tingkah laku kita di dunia nyata mahupun di media sosial?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1010, "siri": "Sirah-01", "no": 10, "nama": "Ali bin Abi Talib", "tajuk": "Saidina Ali bin Abi Talib RA — Gadai Nyawa Di Katil Nabi & Kedudukan Harun", "lokasi": "Malam 27 Safar Tahun 14 Kenabian (622 M) & 9 Hijrah (630 M)", "ibrah": "Keberanian Muda, Kesetiaan Kepimpinan & Amanah", "sumber": "Sahih Al-Bukhari 3706", "link": "https://sunnah.com/bukhari:3706", "tema": "Kepimpinan & Keberanian", "hook": "Bayangkan anda diminta tidur di atas katil seseorang yang sedang dikepung oleh sekumpulan pembunuh bersenjata tajam di luar pintu rumah!", "body": ["Itulah keberanian luar biasa yang ditunjukkan oleh pemuda bernama Saidina Ali bin Abi Talib RA pada malam Hijrah Rasulullah S.A.W.", "Para pemuda terpilih daripada setiap kabilah Quraisy telah mengepung rumah Baginda S.A.W. dengan rancangan untuk menetak tubuh Baginda secara serentak apabila Baginda keluar.", "Namun, walaupun diancam maut, Rasulullah S.A.W. masih memikirkan barangan amanah penduduk Makkah yang disimpan pada Baginda.", "Baginda meminta Ali bin Abi Talib RA tidur di atas katil Baginda berselimutkan kain Burdah Hadrami berwarna hijau milik Baginda.", "Tujuannya jelas: mengelirukan pengepung di luar dan memastikan Ali RA dapat memulangkan semula setiap barang amanah kepada pemiliknya di Makkah sebelum menyusul ke Madinah.", "Ali RA tidur dengan tenang di atas katil tersebut, mempertaruhkan nyawanya demi keselamatan Rasulullah S.A.W. dan kesempurnaan amanah.", "Kesetiaan dan kecekapan Ali RA menguruskan amanah di belakang tabir berulang lagi ketika Perang Tabuk (9 Hijrah).", "Apabila Rasulullah S.A.W. melantik Ali RA menjaga keluarga dan keselamatan kota Madinah, golongan munafik menyindir kononnya Baginda tidak sukakan Ali.", "Ali RA mengejar Baginda lalu mengadu, dan Rasulullah S.A.W. menjawab dengan sabda yang amat mulia di dalam Sahih Al-Bukhari:", "\"Tidakkah engkau reda wahai Ali, bahawa kedudukanmu di sisiku adalah umpama kedudukan Nabi Harun di sisi Nabi Musa, cuma tiada lagi nabi selepas daripadaku?\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Integriti Amanah Walaupun Ketika Diancam: Dalam situasi paling genting sekalipun, Rasulullah S.A.W. dan Ali RA tetap memastikan hak dan barang simpanan orang lain dipulangkan dengan sempurna.", "Keberanian Orang Muda Membina Sejarah: Usia muda bukan alasan untuk mengelak tanggungjawab besar; keberanian dan kesetiaan pada usia remaja mampu menyelamatkan sebuah perjuangan.", "Setiap Peranan Dalam Pasukan Adalah Mulia: Sama ada ditugaskan di barisan hadapan mahupun menjaga pengkalan di belakang tabir, nilai seseorang diukur pada ketaatannya melaksanakan amanah pemimpin.", "Adakah kita melaksanakan setiap tugasan yang diamanahkan kepada kita dengan sepenuh hati tanpa mempedulikan sindiran orang sekeliling?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1011, "siri": "Sirah-01", "no": 11, "nama": "Ali bin Abi Talib", "tajuk": "Saidina Ali bin Abi Talib RA — Pemegang Panji Kemenangan Khaibar", "lokasi": "Muharram 7 Hijrah (Mei 628 M) | Pengepungan Kubu Khaibar", "ibrah": "Validasi Tuhan, Ketaatan Tanpa Alasan & Fokus Dakwah", "sumber": "Sahih Al-Bukhari 4210", "link": "https://sunnah.com/bukhari:4210", "tema": "Kepimpinan & Keberanian", "hook": "Semalaman para sahabat tidak lena tidur kerana masing-masing berharap nama merekalah yang akan dipanggil oleh Rasulullah S.A.W. pada keesokan paginya!", "body": ["Peristiwa mendebarkan ini berlaku semasa pengepungan kubu kuat Khaibar pada tahun ke-7 Hijrah, seperti yang diriwayatkan oleh Sahl bin Sa'ad RA di dalam Sahih Al-Bukhari.", "Selepas beberapa hari kubu Khaibar sukar ditembusi, Rasulullah S.A.W. membuat satu pengumuman yang menggetarkan jiwa setiap tentera Islam:", "\"Esok, aku akan menyerahkan panji perang ini kepada seorang lelaki yang Allah akan mengurniakan kemenangan melalui kedua-dua tangannya. Dia mencintai Allah dan Rasul-Nya, dan Allah serta Rasul-Nya juga mencintai dirinya!\"", "Bayangkan betapa mahalnya pengiktirafan tersebut.", "Bukan sekadar gelaran panglima, tetapi jaminan bahawa Allah dan Rasul-Nya mencintai insan tersebut!", "Keesokan paginya, seluruh sahabat berkumpul awal di hadapan Rasulullah S.A.W. dengan penuh harapan.", "Tiba-tiba Baginda S.A.W. bertanya, \"Di manakah Ali bin Abi Talib?\"", "Para sahabat menjawab, \"Wahai Rasulullah, beliau sedang mengalami sakit mata yang teruk.\"", "Baginda memerintahkan agar Ali RA dipanggil menghadap.", "Ketika Ali RA dipimpin datang dalam keadaan matanya bengkak dan sakit, Rasulullah S.A.W. menyapukan sedikit air liur Baginda yang penuh berkat ke mata Ali RA sambil mendoakannya.", "Dengan izin Allah, mata Ali RA sembuh serta-merta seolah-olah tidak pernah mengalami sebarang kesakitan!", "Baginda menyerahkan panji tersebut kepadanya sambil berpesan:", "\"Maralah dengan tenang. Apabila engkau tiba di halaman mereka, ajaklah mereka kepada Islam terlebih dahulu. Demi Allah, sekiranya seorang manusia mendapat hidayah melalui dirimu, itu jauh lebih baik bagimu daripada memiliki unta-unta merah yang paling mahal!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Kejar Pengiktirafan Allah Melebihi Pujian Manusia: Kemuncak kejayaan sebenar seorang mukmin bukanlah pangkat duniawi, tetapi apabila namanya disenaraikan sebagai hamba yang mencintai dan dicintai Allah.", "Keberkatan Hadir Bersama Ketaatan: Walaupun diuji dengan kesakitan fizikal, Ali RA tetap hadir menyahut panggilan Rasulullah S.A.W. tanpa beralasan, lalu Allah mengangkat kesakitannya.", "Matlamat Utama Adalah Menyelamatkan Manusia, Bukan Menghukum: Walaupun di medan perang, Rasulullah S.A.W. mengajar Ali RA agar mendahulukan dakwah dan bimbingan kerana nilai hidayah seorang insan melebihi segala harta dunia.", "Dalam kesibukan kita mengejar pencapaian kerjaya dan bisnes, adakah kita turut berusaha meraih cinta Allah dan memberi manfaat hidayah kepada orang lain?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1012, "siri": "Sirah-01", "no": 12, "nama": "Ali bin Abi Talib", "tajuk": "Saidina Ali bin Abi Talib RA — Menimba Air Perigi Demi Segenggam Kurma", "lokasi": "Fasa Madinah | Kesederhanaan Hidup & Usaha Halal Saidina Ali RA", "ibrah": "Maruah Kerja Keras, Kesederhanaan & Usaha Halal", "sumber": "Jami' At-Tirmidhi 2473", "link": "https://sunnah.com/tirmidhi:2473", "tema": "Akhlak & Adab", "hook": "Siapa sangka, menantu kesayangan Rasulullah S.A.W. dan pahlawan terbilang Islam pernah menahan lapar di musim sejuk sehingga sanggup bekerja menimba air perigi dengan upah sebiji kurma bagi setiap timba!", "body": ["Kisah benar yang menyentuh hati ini diriwayatkan di dalam Jami' At-Tirmidhi daripada Saidina Ali bin Abi Talib RA sendiri.", "Pada suatu hari yang amat sejuk di Madinah, Ali RA keluar dari rumahnya dalam keadaan perut yang sangat lapar.", "Sekiranya ada sedikit makanan di rumah Rasulullah S.A.W. ketika itu, sudah tentu mereka dapat menjamahnya, namun dapur Baginda juga tiada makanan.", "Demi menahan kesejukan angin Madinah, Ali RA mengambil sehelai kulit kambing yang telah disamak, melubangkannya di bahagian tengah untuk disarungkan ke leher, lalu mengikat pinggangnya dengan pelepah kurma.", "Beliau berjalan keluar mencari pekerjaan yang halal untuk mendapatkan makanan.", "Di pinggir kebun, beliau melihat seorang lelaki Yahudi sedang menimba air dari perigi menggunakan takal untuk menyiram tanaman.", "Melihat Ali RA memerhati dari celah pagar, pemilik kebun itu bertanya:", "\"Wahai orang Arab, mahukah engkau bekerja menimba air untukku dengan upah sebiji kurma bagi setiap satu timba yang engkau tarik?\"", "Ali RA terus bersetuju: \"Ya, bukalah pintu pagar supaya aku dapat masuk bekerja.\"", "Dengan kudrat tangannya sendiri, Ali RA menarik timba demi timba air yang berat dari dasar perigi.", "Setiap kali satu timba naik, beliau diberikan sebiji kurma.", "Apabila jumlah kurma di tangannya sudah mencukupi sekadar untuk mengalas perut dan dikongsi bersama Rasulullah S.A.W., beliau meletakkan timba, meminum air perigi, lalu menuju ke Masjid Nabawi untuk makan bersama Baginda S.A.W.", "3 Pengajaran (Ibrah) Untuk Kita:", "Tiada Kerja Halal Yang Hina: Seorang tokoh besar seperti Ali RA tidak pernah berasa malu melakukan kerja buruh yang berat demi mencari sesuap rezeki yang halal tanpa meminta-minta.", "Sifat Qana'ah (Berpada Dengan Yang Cukup): Apabila upah kurma yang dikumpul sudah mencukupi untuk keperluan hari tersebut, Ali RA berhenti dengan penuh rasa syukur dan terus berkongsi rezeki itu bersama Rasulullah S.A.W.", "Kemuliaan Tidak Diukur Pada Kemewahan Pakaian: Walaupun hanya memakai pakaian kulit yang diikat pelepah kurma, maruah dan kedudukan Ali RA tetap mulia di sisi Allah dan Rasul-Nya.", "Pernahkah kita mengeluh dengan sedikit kesusahan kerja harian, sedangkan insan yang dijamin Syurga sendiri bekerja keras membanting tulang demi segenggam kurma?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1013, "siri": "Sirah-01", "no": 13, "nama": "Talhah bin Ubaidillah", "tajuk": "Saidina Talhah bin Ubaidillah RA — Perisai Hidup Sehingga Jari Lumpuh", "lokasi": "7 Syawal 3 Hijrah (Mac 625 M) | Perang Uhud, Madinah", "ibrah": "Pengorbanan Fizikal, Kesetiaan & Tiada Alasan", "sumber": "Sahih Al-Bukhari 4063", "link": "https://sunnah.com/bukhari:4063", "tema": "Kepimpinan & Keberanian", "hook": "Ketika hujan anak panah musuh menuju tepat ke wajah Rasulullah S.A.W., lelaki ini menghulurkan tapak tangannya sendiri untuk menahan mata panah sehingga jari-jarinya lumpuh seumur hidup!", "body": ["Kisah keberanian luar biasa Saidina Talhah bin Ubaidillah RA ini dirakamkan secara sahih oleh Imam Al-Bukhari menerusi kesaksian Qais bin Abi Hazim.", "Semasa Perang Uhud berubah menjadi genting akibat serangan balas pasukan berkuda musyrikin dari arah belakang, barisan tentera Islam menjadi kucar-kacir.", "Ketika itu, hanya segelintir kecil sahabat termasuk Talhah bin Ubaidillah RA dan Sa'ad bin Abi Waqqas RA yang kekal berdiri rapat mengelilingi Rasulullah S.A.W.", "Musuh mengepung rapat dan melepaskan anak panah bertubi-tubi ke arah Baginda S.A.W.", "Talhah RA melompat ke hadapan menjadikan tubuh badannya sebagai perisai hidup!", "Beliau menangkis libasan pedang dan menahan anak panah yang meluru ke arah wajah Rasulullah S.A.W. menggunakan tangannya sendiri.", "Sebatang anak panah yang tajam menembusi urat saraf tangan Talhah RA sehingga jari-jemarinya hancur dan lumpuh kekal.", "Di akhir pertempuran Uhud itu, tubuh Talhah RA dipenuhi lebih 70 liang luka tikaman tombak, tetakan pedang, dan tusukan panah.", "Qais bin Abi Hazim meriwayatkan di dalam Sahih Al-Bukhari:", "\"Aku telah melihat sendiri tangan Talhah yang lumpuh itu, yang telah digunakannya untuk melindungi Nabi S.A.W. pada hari Perang Uhud.\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Kesetiaan Sebenar Teruji Ketika Krisis: Kesetiaan seseorang kepada perjuangan dan pemimpinnya tidak diukur ketika waktu senang dan menang, tetapi siapa yang kekal bertahan ketika diuji kekalahan.", "Cinta Kepada Rasulullah S.A.W. Menuntut Pengorbanan: Para sahabat sanggup mengorbankan anggota tubuh mereka sendiri demi memastikan keselamatan Baginda dan kelangsungan agama Islam yang sampai kepada kita hari ini.", "Parut Perjuangan Adalah Tanda Kemuliaan: Tangan Talhah RA yang lumpuh bukanlah satu kecacatan yang memalukan, bahkan menjadi bukti abadi pengorbanan beliau yang disanjung tinggi oleh seluruh generasi Islam.", "Apakah sumbangan dan pengorbanan yang telah kita lakukan untuk mempertahankan sunnah dan ajaran yang ditinggalkan oleh Rasulullah S.A.W.?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1014, "siri": "Sirah-01", "no": 14, "nama": "Talhah bin Ubaidillah", "tajuk": "Saidina Talhah bin Ubaidillah RA — Belakang Badan Menjadi Tangga Buat Nabi", "lokasi": "7 Syawal 3 Hijrah (Mac 625 M) | Bukit Uhud, Madinah", "ibrah": "Merendah Diri Demi Mengangkat Pemimpin & Khidmat", "sumber": "Jami' At-Tirmidhi 3738", "link": "https://sunnah.com/tirmidhi:3738", "tema": "Akhlak & Adab", "hook": "\"Telah wajiblah Syurga buat Talhah!\"", "body": ["Sabda keramat itu keluar terus daripada lisan Rasulullah S.A.W. sebaik sahaja Baginda berjaya naik ke atas bongkah batu besar di Bukit Uhud.", "Kisah yang diriwayatkan oleh Az-Zubair bin Al-Awwam RA di dalam Jami' At-Tirmidhi ini menggambarkan kemuncak pengorbanan dan kerendahan hati Saidina Talhah bin Ubaidillah RA.", "Pada penghujung Perang Uhud, tubuh Rasulullah S.A.W. mengalami kecederaan parah.", "Wajah Baginda berdarah, gigi geraham Baginda patah, dan lutut Baginda luka.", "Tambahan pula, pada hari tersebut Rasulullah S.A.W. memakai dua lapis baju besi yang amat berat.", "Ketika Baginda cuba memanjat ke atas sebuah batu besar di lereng Bukit Uhud untuk berlindung dan meninjau keadaan tentera, Baginda tidak berdaya untuk naik kerana beban dua baju besi dan keletihan yang teramat sangat.", "Melihat keadaan cemas itu, Talhah bin Ubaidillah RA yang dirinya sendiri sedang berlumuran darah dengan puluhan luka terus meluru ke bawah batu tersebut.", "Beliau duduk membongkok di bawah Rasulullah S.A.W. dan menjadikan belakang badannya sebagai tangga pijakan!", "Dengan berpijak di atas bahu dan belakang Talhah RA, Rasulullah S.A.W. diangkat naik sehingga selamat berdiri di atas batu besar itu.", "Mendengar tindakan luar biasa Talhah RA itu, Rasulullah S.A.W. terus bersabda:", "\"Telah wajiblah (Syurga) bagi Talhah!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Merendahkan Diri Demi Mengangkat Kebenaran: Talhah RA sanggup membongkokkan tubuhnya di tanah untuk mengangkat Rasulullah S.A.W., dan kerana kerendahan hati itulah Allah mengangkat darjatnya ke Syurga.", "Menjadi Sistem Sokongan (Support System) Yang Kukuh: Dalam organisasi atau keluarga, kejayaan besar dicapai apabila ahli pasukan sedia menjadi tulang belakang yang menyokong dan mengangkat satu sama lain ketika lemah.", "Jangan Biarkan Kesakitan Sendiri Menghalang Kita Membantu Orang Lain: Walaupun tubuh Talhah RA sendiri cedera parah, beliau tetap mengutamakan keperluan Rasulullah S.A.W. melebihi kesakitannya sendiri.", "Adakah kita tergolong dalam kalangan insan yang suka mengangkat dan memudahkan urusan orang lain, atau sebaliknya?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1015, "siri": "Sirah-01", "no": 15, "nama": "Talhah bin Ubaidillah", "tajuk": "Saidina Talhah bin Ubaidillah RA — Syahid Yang Berjalan Di Muka Bumi & Jutawan Pemurah", "lokasi": "Fasa Madinah | Kehidupan Selepas Perang Uhud", "ibrah": "Bangkit Selepas Ujian, Kedermawanan & Pengurusan Harta", "sumber": "Jami' At-Tirmidhi 3739", "link": "https://sunnah.com/tirmidhi:3739", "tema": "Infaq & Harta", "hook": "\"Sesiapa yang gembira untuk melihat seorang syahid yang masih berjalan di atas muka bumi, maka lihatlah kepada Talhah bin Ubaidillah!\"", "body": ["Hadis sahih riwayat Imam At-Tirmidhi daripada Jabir bin Abdullah RA ini merakamkan gelaran paling unik yang pernah diberikan oleh Rasulullah S.A.W. kepada seorang sahabat yang masih hidup.", "Lazimnya, gelaran syahid hanya diberikan kepada mereka yang telah gugur di medan perang.", "Namun kerana Talhah RA telah mempertaruhkan seluruh nyawanya di Perang Uhud tanpa sedikit pun rasa gentar, Allah memanjangkan usianya sambil menganugerahkan maqam syahid ketika beliau masih bernafas di dunia!", "Tetapi, adakah selepas tangannya lumpuh dan dijamin Syurga, Talhah RA hanya duduk berehat mengharapkan bantuan orang lain?", "Sama sekali tidak!", "Dengan sebelah tangan yang masih sihat dan fikiran yang tajam, Talhah RA bangkit mengusahakan perniagaan dan pertanian sehingga menjadi antara usahawan paling berjaya di Madinah.", "Lebih mengagumkan, seluruh kekayaan itu tidak pernah mengikat hatinya.", "Pada suatu malam, isterinya melihat Talhah RA resah gelisah tidak dapat melelapkan mata selepas menerima hasil perniagaan berjumlah ratusan ribu dirham.", "Apabila ditanya puncanya, Talhah RA menjawab bahawa beliau bimbang tidur dalam keadaan harta sebanyak itu masih tersimpan di dalam rumahnya tanpa diagihkan kepada fakir miskin.", "Keesokan paginya, beliau membahagikan kesemua wang tersebut sehingga habis kepada golongan yang memerlukan, sehingga beliau digelar oleh Rasulullah S.A.W. sebagai Talhah Al-Fayyadh (Talhah Yang Melimpah Ruah Kemurahan Hatinya).", "3 Pengajaran (Ibrah) Untuk Kita:", "Kekurangan Fizikal Bukan Penghalang Kejayaan: Walaupun sebelah tangannya lumpuh akibat luka perang, Talhah RA tidak menjadikannya alasan untuk bergantung kepada orang lain, malah bangkit membina empayar perniagaan yang besar.", "Jaminan Kebaikan Tidak Menjadikan Kita Malas: Walaupun telah dijanjikan Syurga secara langsung oleh Nabi S.A.W., Talhah RA terus beramal, bekerja keras, dan bersedekah sepanjang hayatnya.", "Ketenangan Hati Terletak Pada Memberi, Bukan Menyimpan: Orang yang berjiwa besar berasa gelisah jika hartanya hanya bertimbun tanpa memberi manfaat kepada masyarakat yang memerlukan di sekelilingnya.", "Apakah alasan yang masih menghalang kita daripada berusaha gigih dan berkongsi rezeki pada hari ini?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1016, "siri": "Sirah-01", "no": 16, "nama": "Az-Zubair bin Al-Awwam", "tajuk": "Saidina Az-Zubair bin Al-Awwam RA — Hawari (Penolong Setia) Rasulullah SAW", "lokasi": "Syawal 5 Hijrah (Mac 627 M) | Perang Ahzab (Khandaq), Madinah", "ibrah": "Inisiatif Tinggi, Keberanian & Menyahut Tugas Berat", "sumber": "Sahih Al-Bukhari 3719", "link": "https://sunnah.com/bukhari:3719", "tema": "Kepimpinan & Keberanian", "hook": "\"Setiap Nabi itu mempunyai seorang Hawari (penolong setia yang paling rapat), dan sesungguhnya Hawari aku ialah Az-Zubair bin Al-Awwam!\"", "body": ["Pengiktirafan agung daripada lisan Rasulullah S.A.W. ini dirakamkan secara sahih di dalam kitab Sahih Al-Bukhari menerusi riwayat Jabir bin Abdullah RA.", "Bagaimanakah Saidina Az-Zubair bin Al-Awwam RA meraih gelaran yang begitu tinggi itu?", "Peristiwa ini berlaku ketika umat Islam dikepung hebat semasa Perang Ahzab (Khandaq).", "Bayangkan suasana malam yang sangat genting di Madinah.", "Di seberang parit, 10,000 tentera bersekutu musyrikin sedang mengepung dari arah luar.", "Cuaca malam itu sejuk mencengkam tulang, angin ribut bertiup kencang, dan bekalan makanan hampir terputus.", "Tiba-tiba tersebar berita bahawa kaum Bani Quraizah di bahagian dalam kota Madinah telah mengkhianati perjanjian damai.", "Jika berita itu benar, wanita dan kanak-kanak Islam berada dalam bahaya besar diserang dari arah belakang!", "Rasulullah S.A.W. bertanya kepada para sahabat yang sedang menggigil kesejukan dan keletihan:", "\"Siapakah yang sanggup pergi membawa berita tentang keadaan kaum Bani Quraizah kepada kami?\"", "Suasana sepi kerana masing-masing terlalu letih dan kesejukan, namun Az-Zubair bin Al-Awwam RA terus bangkit menyahut, \"Saya, wahai Rasulullah!\"", "Rasulullah S.A.W. mengulangi soalan yang sama buat kali kedua, dan sekali lagi hanya Az-Zubair RA yang bangkit menawarkan diri, \"Saya, wahai Rasulullah!\"", "Apabila Baginda bertanya buat kali ketiga, Az-Zubair RA tetap berdiri tegas menyahut cabaran tersebut tanpa menoleh kiri atau kanan.", "Beliau memacu kudanya meredah kegelapan malam bersendirian ke kawasan musuh, mengumpul maklumat risikan yang tepat, dan kembali dengan selamat kepada Rasulullah S.A.W.", "3 Pengajaran (Ibrah) Untuk Kita:", "Inisiatif Tinggi Ketika Orang Lain Ragu-Ragu: Ciri insan cemerlang adalah kesediaan mengangkat tangan dan memikul tugasan sukar apabila orang lain memilih untuk berdiam diri.", "Konsistensi Dalam Kesetiaan: Tiga kali Rasulullah S.A.W. menguji kesediaan para sahabat, dan ketiga-tiga kali itu Az-Zubair RA tampil tanpa sedikit pun rasa teragak-agak.", "Keberanian Menyelesaikan Krisis: Maklumat tepat yang dibawa pulang oleh Az-Zubair RA membolehkan Rasulullah S.A.W. menyusun langkah strategik untuk menyelamatkan kota Madinah.", "Apabila amanah atau tugasan mencabar dibentangkan di tempat kerja mahupun dalam masyarakat, adakah kita menjadi orang pertama yang tampil membantu?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1017, "siri": "Sirah-01", "no": 17, "nama": "Az-Zubair bin Al-Awwam", "tajuk": "Saidina Az-Zubair bin Al-Awwam RA — Parut Luka Dalam Di Bahu Sejak Badr Hingga Yarmuk", "lokasi": "2 Hijrah (624 M) hingga 15 Hijrah (636 M) | Medan Badr & Medan Yarmuk", "ibrah": "Memimpin Dari Hadapan, Ketahanan Mental & Keberanian", "sumber": "Sahih Al-Bukhari 3721", "link": "https://sunnah.com/bukhari:3721", "tema": "Kepimpinan & Keberanian", "hook": "\"Ketika aku masih kanak-kanak, aku biasa memasukkan jari-jariku ke dalam lubang-lubang parut luka di bahu ayahku ketika bermain!\"", "body": ["Begitulah kesaksian Urwah bin Az-Zubair di dalam Sahih Al-Bukhari tentang betapa dalamnya parut luka perjuangan di tubuh ayahnya, Saidina Az-Zubair bin Al-Awwam RA.", "Sepanjang hidupnya, tubuh Az-Zubair RA menjadi saksi kepada keberanian yang tiada tolok bandingnya.", "Semasa Perang Badr Al-Kubra, Az-Zubair RA tampil di barisan paling hadapan mengenakan serban berwarna kuning.", "Dalam pertempuran sengit itu, bahunya terkena tetakan senjata musuh sehingga meninggalkan lekukan parut yang amat dalam.", "Namun, luka yang dalam itu langsung tidak mematahkan semangat kepahlawanannya.", "Bertahun-tahun kemudian, ketika tentera Islam berdepan ketumbukan raksasa tentera Rom Byzantine dalam Perang Yarmuk, barisan hadapan musuh kelihatan seperti tembok besi yang sukar ditembusi.", "Para sahabat datang menemui Az-Zubair RA lalu berkata:", "\"Tidakkah engkau mahu menyerbu ke arah barisan musuh itu supaya kami semua dapat menyerbu bersama-sama di belakangmu?\"", "Tanpa berlengah, Az-Zubair RA memacu kudanya memecut laju merempuh barisan tentera Rom yang berlapis-lapis itu!", "Beliau membelah barisan musuh sehingga menembusi ke bahagian belakang mereka, kemudian berpusing semula merempuh kembali ke arah kem tentera Islam.", "Dalam rempuhan luar biasa di Yarmuk itu, bahu beliau terkena lagi dua tetakan pedang yang mengapit parut lama Perang Badr, namun keberanian beliau berjaya meruntuhkan ketakutan dan membuka jalan kemenangan buat tentera Islam!", "3 Pengajaran (Ibrah) Untuk Kita:", "Kepimpinan Melalui Teladan (Lead From The Front): Pemimpin sejati tidak sekadar memberi arahan dari belakang, tetapi berani membuka jalan dan merempuh halangan terlebih dahulu untuk membangkitkan semangat pasukannya.", "Ketahanan Mental Melepasi Trauma Lama: Walaupun pernah mengalami kecederaan parah di bahu semasa Perang Badr, Az-Zubair RA tidak pernah menjadikan trauma masa lalu sebagai alasan untuk berundur.", "Tindakan Berani Memecahkan Tembok Ketakutan: Sering kali sesebuah pasukan hanya memerlukan seorang perintis yang berani memulakan langkah pertama untuk membuktikan bahawa cabaran besar boleh ditewaskan.", "Adakah kita berani memulakan langkah pertama untuk memecahkan kebuntuan dalam keluarga dan organisasi kita?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1018, "siri": "Sirah-01", "no": 18, "nama": "Az-Zubair bin Al-Awwam", "tajuk": "Saidina Az-Zubair bin Al-Awwam RA — Rahsia \"Hutang Amanah\" & Keberkatan Harta Tanah", "lokasi": "36 Hijrah (656 M) | Pengurusan Harta Pusaka & Amanah Az-Zubair RA", "ibrah": "Bijak Mengurus Aset, Amanah Kewangan & Wasiat Hutang", "sumber": "Sahih Al-Bukhari 3129", "link": "https://sunnah.com/bukhari:3129", "tema": "Infaq & Harta", "hook": "Beliau meninggal dunia dengan meninggalkan rekod tanggungan \"hutang\" berjumlah lebih dua juta dirham, namun apabila tanah miliknya dijual, kesemua hutang itu langsai sepenuhnya malah berbaki puluhan juta dirham!", "body": ["Kisah luar biasa yang direkodkan secara terperinci di dalam Sahih Al-Bukhari ini membongkar kebijaksanaan kewangan dan tahap integriti Saidina Az-Zubair bin Al-Awwam RA.", "Mengapakah seorang sahabat agung mempunyai rekod hutang sebanyak itu?", "Rupa-rupanya, ia bukanlah hutang kerana berbelanja mewah atau meminjam wang!", "Kerana kejujuran Az-Zubair RA yang sangat tinggi, ramai penduduk datang menemui beliau untuk menumpangkan wang simpanan mereka sebagai Wadi'ah (simpanan amanah).", "Namun, mengikut fiqh Islam, jika barang simpanan amanah (Wadi'ah) hilang tanpa kecuaian, pemegang amanah tidak wajib menggantikannya.", "Az-Zubair RA sangat takut jika wang orang ramai itu hilang, lalu beliau berkata kepada setiap pendeposit:", "\"Janganlah kamu jadikannya sebagai simpanan biasa, tetapi anggaplah ia sebagai pinjaman (hutang) ke atasku. Sesungguhnya aku bimbang wangmu hilang (kerana jika dianggap hutang, aku dan warisku wajib menggantikannya 100% walaupun berlaku sebarang musibah)!\"", "Sebelum gugur syahid, Az-Zubair RA berwasiat kepada anaknya, Abdullah bin Az-Zubair RA:", "\"Wahai anakku, selesaikanlah segala hutangku. Sekiranya engkau menghadapi kesukaran dalam melunaskan mana-mana bahagian daripadanya, berdoalah meminta pertolongan daripada Maula (Pelindung) aku, iaitu Allah SWT!\"", "Selepas Az-Zubair RA wafat, sebidang tanah hutan miliknya di Al-Ghabah yang dahulunya dibeli pada harga 170,000 dirham telah meningkat nilainya menjadi 1,600,000 dirham!", "Abdullah bin Az-Zubair RA menjual sebahagian hartanah tersebut, melunaskan setiap satu sen tuntutan amanah orang ramai sambil membuat pengumuman terbuka selama empat musim Haji berturut-turut, dan baki harta pusaka yang halal masih mencecah puluhan juta dirham!", "3 Pengajaran (Ibrah) Untuk Kita:", "Integriti Kewangan Tahap Tertinggi: Az-Zubair RA sanggup menukar status wang simpanan orang ramai menjadi hutang peribadi semata-mata untuk memberi jaminan perlindungan 100% kepada pemilik asal.", "Keberkatan Pelaburan Aset Sebenar: Beliau tidak membiarkan modal terbiar, sebaliknya melaburkannya ke dalam aset tanah produktif yang nilainya berkembang berlipat kali ganda untuk manfaat waris.", "Kewajipan Mengutamakan Penyelesaian Hutang: Abdullah bin Az-Zubair RA menangguhkan pembahagian pusaka selama empat tahun dan mengisytiharkan di musim Haji semata-mata bagi memastikan tiada walau seorang pemiutang pun yang tertinggal.", "Sudahkah kita merekodkan segala hutang dan amanah kewangan kita secara bertulis agar mudah diuruskan oleh waris kelak?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1019, "siri": "Sirah-01", "no": 19, "nama": "Abdurrahman bin Auf", "tajuk": "Saidina Abdurrahman bin Auf RA — \"Tunjukkan Aku Di Mana Pasar\"", "lokasi": "1 Hijrah (622 M) | Permulaan Hijrah Di Madinah Al-Munawwarah", "ibrah": "Maruah Diri, Mindset Usahawan & Berdikari", "sumber": "Sahih Al-Bukhari 2048", "link": "https://sunnah.com/bukhari:2048", "tema": "Infaq & Harta", "hook": "Ditawarkan separuh kekayaan milik orang paling kaya di Madinah secara percuma, namun lelaki yang baru tiba sehelai sepinggang ini menolak dengan penuh hormat dan hanya meminta ditunjukkan lokasi pasar!", "body": ["Kisah ikonik di dalam Sahih Al-Bukhari ini merupakan manifesto maruah diri dan keusahawanan paling hebat dalam sejarah Islam.", "Apabila Saidina Abdurrahman bin Auf RA berhijrah dari Makkah ke Madinah, beliau meninggalkan seluruh kekayaan dan perniagaan lamanya demi mempertahankan iman.", "Setibanya di Madinah, Rasulullah S.A.W. mempersaudarakan beliau dengan seorang hartawan Ansar yang sangat pemurah bernama Sa'ad bin Ar-Rabi' RA.", "Sa'ad RA berkata dengan penuh keikhlasan:", "\"Wahai saudaraku, aku adalah orang yang paling banyak harta dalam kalangan penduduk Madinah. Ambillah separuh daripada hartaku ini untukmu!\"", "Bayangkan jika tawaran modal percuma sebesar itu diberikan kepada manusia biasa yang sedang kesempitan.", "Namun, Abdurrahman bin Auf RA mempunyai prinsip maruah diri yang luar biasa tinggi.", "Beliau mendoakan sahabatnya itu dengan ucapan yang sangat indah:", "\"Semoga Allah memberkati buatmu pada ahli keluargamu dan juga pada hartamu. Aku tidak memerlukan semua itu. Cuma tunjukkanlah kepadaku di manakah terletaknya pasar tempat orang berniaga?\"", "Sa'ad RA menunjukkan arah ke Pasar Bani Qainuqa'.", "Keesokan paginya, Abdurrahman RA pergi ke pasar tersebut, memulakan perniagaan jual beli keju kering (aqit) dan minyak sapi (samin).", "Dalam masa beberapa hari sahaja, keuntungan perniagaannya berkembang pesat sehingga beliau mampu berkahwin dengan mahar emas seberat biji kurma dan membina empayar perniagaan terbesar di Madinah!", "3 Pengajaran (Ibrah) Untuk Kita:", "Maruah Diri Melebihi Jalan Pintas: Orang yang berjiwa mulia tidak suka mengambil kesempatan atas kemurahan hati kawan atau mengharapkan pemberian percuma selagi masih mempunyai tulang empat kerat untuk berusaha.", "Ilmu Dan Peluang Lebih Bernilai Daripada Modal Tunai: Abdurrahman RA membuktikan bahawa seorang usahawan yang memiliki kemahiran dan memahami pasaran mampu bangkit semula walaupun bermula daripada sifar.", "Hargai Pemberian Orang Dengan Doa Terbaik: Walaupun menolak tawaran harta Sa'ad RA, beliau menolaknya dengan penuh adab sambil mendoakan keberkatan keluarga dan harta saudaranya itu.", "Adakah kita masih menunggu modal besar jatuh dari langit, atau kita sudah mula melangkah mencari peluang dengan kemahiran yang ada di tangan?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1020, "siri": "Sirah-01", "no": 20, "nama": "Abdurrahman bin Auf", "tajuk": "Saidina Abdurrahman bin Auf RA — Tangisan Jutawan Ketika Berbuka Puasa", "lokasi": "Fasa Madinah | Muhasabah Diri Seorang Hartawan Syurga", "ibrah": "Takut Istidraj, Syukur Nikmat & Hati Tidak Terikat Dunia", "sumber": "Sahih Al-Bukhari 4045", "link": "https://sunnah.com/bukhari:4045", "tema": "Akhlak & Adab", "hook": "Hidangan berbuka puasa sudah terhidang di hadapan mata, namun jutawan ini tiba-tiba menangis teresak-esak sehingga beliau bangun meninggalkan makanan tersebut!", "body": ["Kisah benar yang menginsafkan jiwa ini diriwayatkan oleh Sa'ad bin Ibrahim di dalam kitab Sahih Al-Bukhari.", "Saidina Abdurrahman bin Auf RA terkenal sebagai salah seorang sahabat terkaya yang diberkati perniagaannya, namun dalam masa yang sama beliau sentiasa menjaga ibadah puasa dan ketaatannya.", "Pada suatu petang ketika beliau sedang berpuasa, dihidangkan kepadanya makanan berbuka yang baik.", "Namun sebaik sahaja memandang hidangan tersebut, air mata Abdurrahman bin Auf RA tiba-tiba mengalir laju membasahi pipinya.", "Beliau teringat kepada sahabat-sahabat seperjuangannya yang telah gugur syahid lebih awal dalam keadaan serba kekurangan.", "Beliau berkata dengan suara yang sebak:", "\"Mus'ab bin Umair telah gugur syahid pada hari Perang Uhud, sedangkan dia adalah seorang yang jauh lebih baik daripadaku. Ketika dia hendak dikafankan, kami hanya menemui sehelai kain Burdah; jika ditutup kepalanya maka terbukalah kakinya, dan jika ditutup kakinya maka terbukalah kepalanya!\"", "Beliau menyambung lagi dalam tangisan:", "\"Hamzah bin Abdul Muttalib juga telah gugur syahid, dan dia juga jauh lebih baik daripadaku. Kemudian dunia ini telah dibentangkan seluas-luasnya kepada kami dan kami dikurniakan harta yang begitu banyak. Sesungguhnya kami amat takut sekiranya pahala kebaikan kami telah disegerakan balasannya di dunia ini sahaja!\"", "Kerana terlalu sebak dan takutkan hisab Allah, Abdurrahman RA terus menangis sehingga beliau tidak mampu menjamah makanan tersebut.", "3 Pengajaran (Ibrah) Untuk Kita:", "Kesenangan Dunia Adalah Ujian, Bukan Ukuran Kemuliaan: Para sahabat memahami bahawa limpahan rezeki bukanlah tanda seseorang lebih mulia berbanding mereka yang diuji dengan kesempitan, sebaliknya ia adalah ujian kesyukuran.", "Sentiasa Mengingati Pengorbanan Generasi Terdahulu: Ketika menikmati keselesaan hidup hari ini, jangan sesekali kita lupa jerih perih mereka yang berkorban di fasa awal perjuangan.", "Rasa Takut (Khauf) Menjaga Hati Orang Kaya: Kerana rasa takut kebaikannya habis dibalas di dunia itulah yang mendorong Abdurrahman bin Auf RA terus menginfaqkan hartanya tanpa henti ke jalan Allah.", "Apabila rezeki kita dilapangkan oleh Allah, adakah hati kita semakin tunduk bersyukur atau semakin lalai dengan kesenangan?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1021, "siri": "Sirah-01", "no": 21, "nama": "Abdurrahman bin Auf", "tajuk": "Saidina Abdurrahman bin Auf RA — Sedekah Kebun 400,000 Dirham & Doa Salsabil", "lokasi": "Fasa Selepas Kewafatan Rasulullah S.A.W. | Madinah Al-Munawwarah", "ibrah": "Menjaga Kebajikan, Membalas Budi & Infaq Terbaik", "sumber": "Jami' At-Tirmidhi 3749", "link": "https://sunnah.com/tirmidhi:3749", "tema": "Infaq & Harta", "hook": "\"Semoga Allah memberi minum kepada bapamu daripada mata air Salsabil di dalam Syurga!\"", "body": ["Doa penuh keberkatan itu diucapkan sendiri oleh Ummul Mukminin Saidatina Aisyah RA kepada Abu Salamah, putera kepada Saidina Abdurrahman bin Auf RA.", "Mengapakah Saidatina Aisyah RA mendoakan ganjaran semulia itu buat Abdurrahman bin Auf RA?", "Kisah sahih ini direkodkan oleh Imam At-Tirmidhi di dalam Jami' At-Tirmidhi.", "Semasa Rasulullah S.A.W. masih hidup, Baginda pernah bersabda kepada isteri-isteri Baginda (Ummahatul Mukminin):", "\"Sesungguhnya urusan kebajikan kamu semua selepas peninggalanku nanti adalah perkara yang paling membimbangkan hatiku. Dan tidak akan ada orang yang mampu bersabar menjaga kebajikan kamu semua melainkan orang-orang yang benar-benar sabar dan ikhlas.\"", "Abdurrahman bin Auf RA mengingati pesanan Rasulullah S.A.W. itu dengan sepenuh jiwanya.", "Selepas kewafatan Baginda S.A.W., Abdurrahman RA mengambil tanggungjawab menyantuni dan membiayai keperluan keluarga serta balu-balu Rasulullah S.A.W. dengan penuh hormat.", "Malah, beliau mewakafkan dan menyedekahkan sebidang tanah kebun miliknya yang sangat bernilai khusus untuk menampung keperluan Ummahatul Mukminin.", "Kebun tersebut kemudiannya dijual dengan nilai mencecah 400,000 dirham (atau 40,000 dinar emas mengikut riwayat) dan seluruh hasilnya diserahkan kepada isteri-isteri Rasulullah S.A.W.!", "Selain itu, beliau turut mewasiatkan 400 dinar emas kepada setiap seorang pejuang Perang Badr yang masih hidup (seramai 100 orang menerima bahagian tersebut termasuk Saidina Uthman dan Ali RA).", "3 Pengajaran (Ibrah) Untuk Kita:", "Bukti Cinta Kepada Sahabat Adalah Menjaga Keluarganya: Tanda kesetiaan sejati kepada Rasulullah S.A.W. dan sahabat seperjuangan adalah dengan terus menjaga kebajikan ahli keluarga mereka selepas mereka tiada.", "Sabar Dalam Berbuat Kebajikan Berterusan: Menjaga kebajikan golongan balu, anak yatim, dan keluarga pejuang menuntut kesabaran serta komitmen kewangan yang konsisten, bukan sekadar bantuan bermusim.", "Harta Yang Diinfaqkan Mengundang Doa Orang Soleh: Sumbangan ikhlas Abdurrahman RA membuahkan doa mustajab daripada Saidatina Aisyah RA agar beliau diberi minum dari mata air Salsabil di Syurga.", "Adakah kita masih mengambil berat dan bertanya khabar keadaan keluarga sahabat atau saudara-mara kita yang telah pergi mendahului kita?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1022, "siri": "Sirah-01", "no": 22, "nama": "Sa'ad bin Abi Waqqas", "tajuk": "Saidina Sa'ad bin Abi Waqqas RA — Mogok Lapar Ibu & Turunnya Surah Luqman: 15", "lokasi": "Fasa Awal Makkah | Ujian Aqidah & Ketaatan Ibu Bapa", "ibrah": "Prinsip Aqidah, Adab Ibu Bapa & Ketahanan Emosi", "sumber": "Sahih Muslim 1748c", "link": "https://sunnah.com/muslim:1748c", "tema": "Keluarga & Wanita", "hook": "\"Bukankah Allah memerintahkan engkau berbuat baik kepada ibu bapa? Demi Allah, aku tidak akan makan dan tidak akan minum sehingga aku mati, atau sehingga engkau kufur meninggalkan agama Muhammad!\"", "body": ["Bayangkan tekanan emosi yang terpaksa ditanggung oleh seorang pemuda remaja yang terkenal paling taat dan menyayangi ibunya apabila diugut sedemikian rupa oleh ibu kandungnya sendiri!", "Kisah benar yang menjadi asbab turunnya ayat Al-Quran ini diriwayatkan di dalam Sahih Muslim mengenai Saidina Sa'ad bin Abi Waqqas RA.", "Apabila ibu Sa'ad RA (Hamnah binti Sufyan) mengetahui anaknya telah memeluk Islam, beliau melancarkan mogok lapar.", "Berhari-hari ibunya enggan menyentuh makanan dan minuman sehingga tubuhnya menjadi terlalu lemah dan hampir pengsan.", "Sehingga apabila mereka mahu memasukkan sedikit makanan ke mulut ibunya, mereka terpaksa membuka mulutnya menggunakan sebatang kayu kecil!", "Penduduk Makkah mengecam Sa'ad RA kononnya beliau bakal menjadi punca kematian ibunya sendiri.", "Namun, Sa'ad RA menunjukkan bagaimana seorang mukmin menggabungkan ketegasan prinsip aqidah dengan adab terhadap seorang ibu.", "Beliau duduk di sisi ibunya lalu berkata dengan tegas tetapi penuh hormat:", "\"Wahai ibuku, ketahuilah demi Allah! Sekiranya ibu mempunyai 100 nyawa sekalipun, lalu nyawa itu keluar satu demi satu di hadapan mataku, aku tetap tidak akan sesekali meninggalkan agamaku ini! Maka terpulanglah sama ada ibu mahu makan ataupun tidak.\"", "Melihat keteguhan iman anaknya yang tidak mungkin goyah, ibunya akhirnya mengalah dan kembali menjamah makanan.", "Rentetan peristiwa itu, Allah SWT menurunkan ayat Al-Quran (Surah Al-Ankabut: 8 dan Surah Luqman: 15) yang memerintahkan agar anak tetap berbuat baik kepada ibu bapa di dunia, namun dilarang mentaati mereka jika disuruh mensyirikkan Allah!", "3 Pengajaran (Ibrah) Untuk Kita:", "Ketaatan Kepada Allah Mengatasi Segala-galanya: Tiada ketaatan kepada mana-mana makhluk dalam perkara yang melanggar perintah Pencipta, walaupun desakan itu datang daripada insan paling rapat.", "Kekal Beradab Walaupun Berbeza Pegangan: Walaupun menolak tuntutan ibunya untuk kembali kepada syirik, Sa'ad RA tetap diperintahkan oleh Allah untuk menyantuni dan berbuat baik kepada ibunya dalam urusan dunia.", "Ketahanan Emosi Menghadapi Tekanan Sosial: Apabila kita berdiri teguh dan jelas dengan prinsip kebenaran tanpa goyah, pihak yang cuba memanipulasi emosi kita akhirnya akan menghormati pendirian tersebut.", "Bagaimanakah kita menjaga keseimbangan antara berbakti kepada ibu bapa dengan ketegasan memelihara syariat Allah dalam keluarga kita?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1023, "siri": "Sirah-01", "no": 23, "nama": "Sa'ad bin Abi Waqqas", "tajuk": "Saidina Sa'ad bin Abi Waqqas RA — Pemanah Pertama & Doa Istimewa Di Uhud", "lokasi": "7 Syawal 3 Hijrah (Mac 625 M) | Perang Uhud, Madinah", "ibrah": "Kemahiran Fokus, Doa Mustajab & Keberanian", "sumber": "Sahih Muslim 2412c", "link": "https://sunnah.com/muslim:2412c", "tema": "Kepimpinan & Keberanian", "hook": "\"Panahlah wahai Sa'ad! Tebusanmu adalah bapa dan ibuku!\"", "body": ["Tahukah anda, dalam sejarah hidup Rasulullah S.A.W., Baginda sangat jarang menggabungkan sebutan \"tebusanmu bapa dan ibuku\" (Fidaka Abi wa Ummi) untuk seorang sahabat melainkan kepada Saidina Sa'ad bin Abi Waqqas RA pada hari Perang Uhud!", "Kisah kemuliaan yang dirakamkan di dalam Sahih Al-Bukhari dan Sahih Muslim ini memaparkan kehebatan Sa'ad bin Abi Waqqas RA sebagai pemanah elit pertama dalam sejarah Islam.", "Ketika Perang Uhud berada di kemuncak bahaya, seorang pahlawan musyrikin sedang mengamuk hebat memanah dan mencederakan tentera Islam.", "Sa'ad bin Abi Waqqas RA duduk berlutut tepat di hadapan Rasulullah S.A.W. untuk melindungi Baginda dengan busur dan anak panahnya.", "Rasulullah S.A.W. sendiri menghulurkan anak-anak panah satu persatu kepada Sa'ad RA sambil memberikan kata-kata semangat yang luar biasa itu:", "\"Panahlah wahai Sa'ad! Tebusanmu adalah bapa dan ibuku!\"", "Setiap kali Sa'ad RA menarik tali busurnya dan melepaskan anak panah, panahannya tepat mengenai sasaran musuh tanpa tersasar.", "Malah, Rasulullah S.A.W. mengangkat tangan mendoakan secara khusus buat Sa'ad RA:", "\"Ya Allah! Tepatkanlah bidikan panahannya dan makbulkanlah doanya!\"", "Berkat doa langsung daripada Rasulullah S.A.W. pada hari itu, Sa'ad bin Abi Waqqas RA menjadi terkenal di seluruh dunia Islam sebagai lelaki yang panahannya tidak pernah tersasar dan doanya kepada Allah sentiasa makbul!", "3 Pengajaran (Ibrah) Untuk Kita:", "Kuasai Kemahiran Sehingga Ke Tahap Pakar: Sa'ad RA mengasah kemahiran memanahnya sehingga menjadi benteng utama yang menyelamatkan Rasulullah S.A.W. di saat paling genting.", "Penghargaan Pemimpin Membakar Semangat: Kata-kata pujian dan doa tulus yang diucapkan oleh Rasulullah S.A.W. kepada Sa'ad RA ketika waktu krisis melipatgandakan keberanian dan fokus beliau.", "Gabungan Usaha Fizikal Dan Kuasa Doa: Kejayaan Sa'ad RA meruntuhkan empayar Parsi di Qadisiyyah kelak lahir daripada gabungan ketepatan strategi ketenteraan dan senjata doa yang mustajab.", "Apakah satu kemahiran utama yang sedang kita asah hari ini untuk memberi sumbangan terbaik kepada agama dan masyarakat?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1024, "siri": "Sirah-01", "no": 24, "nama": "Sa'ad bin Abi Waqqas", "tajuk": "Saidina Sa'ad bin Abi Waqqas RA — Wasiat Satu Pertiga Harta: Jangan Tinggalkan Waris Miskin", "lokasi": "Zulhijjah 10 Hijrah (632 M) | Haji Wada', Makkah Al-Mukarramah", "ibrah": "Perancangan Pusaka, Nafkah Keluarga & Keseimbangan Infaq", "sumber": "Sahih Al-Bukhari 1295", "link": "https://sunnah.com/bukhari:1295", "tema": "Keluarga & Wanita", "hook": "\"Sesungguhnya jika engkau meninggalkan ahli warismu dalam keadaan kaya (berkecukupan), itu jauh lebih baik daripada engkau meninggalkan mereka dalam keadaan miskin sehingga terpaksa menadah tangan meminta-minta kepada manusia!\"", "body": ["Nasihat pengurusan harta dan pusaka yang sangat agung daripada Rasulullah S.A.W. ini lahir daripada kisah sakitnya Saidina Sa'ad bin Abi Waqqas RA di Makkah, seperti yang direkodkan di dalam Sahih Al-Bukhari.", "Semasa berada di Makkah pada tahun Pembukaan Makkah atau Haji Wada', Sa'ad bin Abi Waqqas RA jatuh sakit tenat sehingga beliau menyangka ajalnya sudah tiba.", "Rasulullah S.A.W. datang menziarahi Sa'ad RA untuk bertanya khabar.", "Dalam keadaan lemah, Sa'ad RA berkata kepada Baginda:", "\"Wahai Rasulullah, aku sedang sakit tenat seperti yang engkau lihat. Aku merupakan seorang yang memiliki harta yang banyak, dan ketika ini aku tidak mempunyai waris selain seorang anak perempuan sahaja. Bolehkah aku menyedekahkan dua pertiga (2/3) daripada seluruh hartaku?\"", "Rasulullah S.A.W. menjawab ringkas, \"Tidak boleh.\"", "Sa'ad RA bertanya lagi, \"Bagaimana jika aku sedekahkan separuh (1/2) daripada hartaku, wahai Rasulullah?\"", "Baginda menjawab lagi, \"Tidak boleh.\"", "Sa'ad RA bertanya buat kali ketiga, \"Bagaimana jika satu pertiga (1/3)?\"", "Rasulullah S.A.W. menjawab:", "\"Satu pertiga dibolehkan, dan satu pertiga itu pun sebenarnya sudah banyak! Sesungguhnya engkau meninggalkan ahli warismu dalam keadaan kaya adalah lebih baik daripada engkau meninggalkan mereka miskin meminta-minta kepada orang ramai. Dan tidaklah engkau membelanjakan sesuatu nafkah kerana mencari reda Allah, melainkan engkau pasti diberi pahala atasnya, sekalipun satu suap makanan yang engkau letakkan ke dalam mulut isterimu!\"", "Dengan takdir Allah, selepas doa Nabi S.A.W. pada hari itu, Sa'ad RA sembuh sepenuhnya, hidup panjang selama puluhan tahun lagi, dan dikurniakan ramai lagi cahaya mata!", "3 Pengajaran (Ibrah) Untuk Kita:", "Rancang Kewangan Keluarga Sebelum Pergi: Islam amat menitikberatkan masa depan ekonomi anak-anak dan isteri agar mereka tidak hidup melarat atau meminta-minta selepas kematian ketua keluarga.", "Keseimbangan Antara Sedekah Dan Hak Waris: Walaupun bersedekah itu mulia, syariat menetapkan had maksimum wasiat harta adalah satu pertiga (1/3) supaya hak pewaris sah tidak terabai.", "Nafkah Keluarga Adalah Ibadah Berpahala Besar: Setiap ringgit yang dibelanjakan dengan ikhlas untuk makan minum isteri dan anak-anak dikira sebagai sedekah yang berpahala besar di sisi Allah.", "Sudahkah kita menyediakan perlindungan kewangan dan perancangan pusaka yang tersusun agar keluarga kita terpelihara kelak?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1025, "siri": "Sirah-01", "no": 25, "nama": "Sa'id bin Zaid", "tajuk": "Saidina Sa'id bin Zaid RA — Saksi Hadis 10 Sahabat Dijamin Syurga Di Tengah Fitnah", "lokasi": "Zaman Pemerintahan Bani Umayyah | Masjid Kufah, Iraq", "ibrah": "Membela Kebenaran, Menjaga Ukhuwah & Kesaksian Jujur", "sumber": "Sunan Abu Daud 4649", "link": "https://sunnah.com/abudawud:4649", "tema": "Akhlak & Adab", "hook": "Ketika seorang lelaki bangkit mencela sahabat Nabi S.A.W. di dalam masjid, seorang tokoh tua yang tenang bangun melafazkan kesaksian yang menutup mulut seluruh majlis!", "body": ["Kisah bersejarah yang menjadi sumber utama hadis 10 Sahabat Dijamin Syurga ini diriwayatkan secara sahih di dalam Sunan Abu Daud dan Jami' At-Tirmidhi.", "Tahukah anda siapakah perawi yang menyampaikan hadis 10 Sahabat Dijamin Syurga ini sambil menyembunyikan namanya sendiri pada mulanya kerana sifat tawaduk?", "Beliau ialah Saidina Sa'id bin Zaid RA, ipar dan sepupu kepada Saidina Umar bin Al-Khattab RA, yang memeluk Islam pada fasa paling awal di Makkah sebelum Rasulullah S.A.W. memasuki Darul Arqam lagi.", "Pada suatu hari di Masjid Kufah, seorang lelaki bangun mengucapkan kata-kata buruk terhadap Saidina Ali bin Abi Talib RA.", "Mendengar celaan terhadap sahabat seperjuangannya itu, Sa'id bin Zaid RA tidak sanggup berdiam diri.", "Beliau terus bangkit berdiri dengan penuh wibawa lalu berkata:", "\"Aku bersaksi ke atas Rasulullah S.A.W. bahawa aku telah mendengar dengan telingaku sendiri Baginda bersabda: Sepuluh orang berada di dalam Syurga! Nabi berada di dalam Syurga, Abu Bakar di dalam Syurga, Umar di dalam Syurga, Uthman di dalam Syurga, Ali di dalam Syurga, Talhah di dalam Syurga, Az-Zubair bin Al-Awwam di dalam Syurga, Sa'ad bin Malik (Ibn Abi Waqqas) di dalam Syurga, dan Abdurrahman bin Auf di dalam Syurga...\"", "Selepas menyebut sembilan nama tersebut, Sa'id bin Zaid RA berhenti dan berkata:", "\"Sekiranya aku mahu, aku boleh menyebutkan siapakah orang yang kesepuluh itu!\"", "Orang ramai di dalam masjid merayu dengan nama Allah, \"Wahai Abu Al-A'war, siapakah orang yang kesepuluh itu?\"", "Kerana didesak dengan sumpah nama Allah, barulah beliau menjawab dengan perlahan dan penuh rendah diri: \"Orang yang kesepuluh itu ialah Sa'id bin Zaid!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Wajib Membela Maruah Sahabat Yang Dizalimi: Apabila mendengar rakan atau insan baik difitnah di hadapan kita, jangan sekadar menjadi pemerhati bisu; bangkitlah menyatakan kebenaran dengan fakta.", "Tawaduk Menyembunyikan Kelebihan Diri: Sa'id bin Zaid RA tidak menggunakan jaminan Syurga yang dimilikinya untuk membangga diri, malah hanya menyebut namanya selepas didesak oleh orang ramai.", "Kemuliaan Para Sahabat Adalah Aqidah Umat Islam: Mencintai dan menghormati kesemua sahabat Rasulullah S.A.W. tanpa mencela mana-mana seorang daripada mereka adalah tanda kesempurnaan iman.", "Apabila kita mendengar orang mengumpat atau memfitnah saudara kita, adakah kita berani tampil mempertahankan maruahnya?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1026, "siri": "Sirah-01", "no": 26, "nama": "Sa'id bin Zaid", "tajuk": "Saidina Sa'id bin Zaid RA — Difitnah Merampas Tanah & Doa Orang Teraniaya", "lokasi": "Zaman Pemerintahan Marwan bin Al-Hakam | Madinah Al-Munawwarah", "ibrah": "Bahaya Kezaliman, Kuasa Doa Mazlum & Integriti", "sumber": "Sahih Muslim 1610b", "link": "https://sunnah.com/muslim:1610b", "tema": "Sabar & Tawakal", "hook": "\"Ya Allah! Sekiranya wanita ini berdusta memfitnahku, maka butakanlah matanya dan jadikanlah kuburnya di dalam tanah miliknya sendiri!\"", "body": ["Doa seorang sahabat Nabi S.A.W. yang difitnah pada usia tuanya ini menembusi langit tanpa hijab dan dimakbulkan oleh Allah secara tunai di dunia!", "Kisah benar yang amat menggerunkan hati tentang bahaya fitnah dan rampasan harta ini direkodkan secara sahih di dalam kitab Sahih Muslim.", "Saidina Sa'id bin Zaid RA telah menghabiskan seluruh usianya berjuang bersama Rasulullah S.A.W. dengan penuh kejujuran.", "Namun pada penghujung usianya di Madinah, seorang wanita bernama Arwa binti Uwais membuat tuduhan palsu bahawa Sa'id bin Zaid RA telah mengambil dan menganjak sempadan sebahagian tanah miliknya!", "Arwa membawa kes tuduhan itu ke hadapan Gabenor Madinah ketika itu, Marwan bin Al-Hakam, sehingga mencemarkan nama baik seorang sahabat yang dijamin Syurga.", "Apabila pegawai gabenor datang menemui Sa'id bin Zaid RA untuk menyiasat dakwaan tersebut, Sa'id RA terkejut dan berkata:", "\"Adakah kamu menyangka aku sanggup menzalimi wanita itu setelah aku mendengar sendiri Rasulullah S.A.W. bersabda tentang bahaya merampas tanah?\"", "Demi menjaga maruah dan mengelakkan pertelingkahan dunia, Sa'id RA menyerahkan tanah yang dituntut oleh wanita itu sambil mengangkat tangan berdoa:", "\"Ya Allah! Sesungguhnya wanita ini mendakwa aku telah menzaliminya. Sekiranya dia berdusta, maka butakanlah penglihatannya dan campakkanlah dia ke dalam telaganya sendiri!\"", "Perawi hadis dalam Sahih Muslim menyaksikan sendiri bagaimana tidak lama selepas itu, Arwa binti Uwais menjadi buta sehingga terpaksa berjalan meraba-raba dinding sambil berkata, \"Aku telah terkena doa Sa'id bin Zaid!\"", "Dan pada suatu hari ketika berjalan di kawasan tanahnya itu, wanita tersebut terjatuh ke dalam lubang perigi di rumahnya sendiri lalu meninggal dunia di dalamnya!", "3 Pengajaran (Ibrah) Untuk Kita:", "Takutilah Doa Orang Yang Dizalimi (Doa Mazlum): Jangan sesekali menggunakan kelicikan lidah, kuasa, atau laporan palsu untuk menganiaya orang lain kerana doa insan teraniaya tiada penghalang di sisi Allah.", "Jangan Pertaruhkan Akhirat Kerana Harta Dunia: Apa yang direbut secara batil dan fitnah akhirnya tidak memberi sebarang kebahagiaan, malah boleh menjadi punca kebinasaan diri sendiri.", "Serahkan Keadilan Mutlak Kepada Allah: Apabila kita sudah berkata benar namun masih ditekan dengan fitnah manusia, mengadulah terus kepada Hakim Yang Maha Adil.", "Adakah kita sentiasa berhati-hati agar lidah dan perbuatan kita tidak menzalimi atau mengambil hak orang lain walau sedikit?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1027, "siri": "Sirah-01", "no": 27, "nama": "Sa'id bin Zaid", "tajuk": "Saidina Sa'id bin Zaid RA — Melepaskan Hak Tanah Kerana Takutkan Kalungan Tujuh Bumi", "lokasi": "Fasa Madinah | Pegangan Prinsip Hadis Saidina Sa'id bin Zaid RA", "ibrah": "Ketenangan Jiwa, Melepaskan Rebutan Dunia & Taqwa", "sumber": "Sahih Muslim 1610c", "link": "https://sunnah.com/muslim:1610c", "tema": "Sabar & Tawakal", "hook": "\"Ambillah tanah itu dan biarkanlah dia! Kerana aku pernah mendengar Rasulullah S.A.W. bersabda: Sesiapa yang mengambil sejengkal tanah tanpa haknya, nescaya akan dikalungkan ke lehernya daripada tujuh petala bumi pada Hari Kiamat!\"", "body": ["Mengapakah Saidina Sa'id bin Zaid RA sanggup melepaskan sebahagian tanah miliknya yang sah kepada penuntut yang menuduhnya tanpa mahu bergaduh panjang di mahkamah?", "Jawapannya terletak pada prinsip ketenangan jiwa dan ketakutan beliau yang mendalam terhadap amaran Rasulullah S.A.W. yang diriwayatkannya di dalam Sahih Muslim.", "Ketika Gabenor Marwan bin Al-Hakam bertanya kepada Sa'id bin Zaid RA mengenai pertikaian sempadan tanah dengan Arwa binti Uwais, Sa'id RA bertanya semula:", "\"Bagaimanakah mungkin aku mengambil sebahagian tanahnya setelah apa yang aku dengar sendiri daripada Rasulullah S.A.W.?\"", "Marwan bertanya, \"Apakah yang telah engkau dengar daripada Rasulullah S.A.W.?\"", "Sa'id bin Zaid RA membacakan hadis yang didengarnya secara langsung:", "\"Sesiapa yang mengambil sejengkal tanah secara zalim (tanpa hak), maka Allah akan mengalungkan tujuh petala bumi di lehernya pada Hari Kiamat kelak!\"", "Mendengar kesaksian hadis yang begitu berat itu daripada mulut seorang sahabat agung, Marwan bin Al-Hakam terus berkata:", "\"Aku tidak meminta sebarang bukti lagi daripadamu selepas mendengar hadis ini!\"", "Walaupun gabenor sudah memihak kepadanya, Sa'id bin Zaid RA tetap memilih untuk membiarkan bahagian tanah yang dipertikaikan itu kerana bagi beliau, ketenangan hati dan keselamatan di akhirat jauh lebih mahal daripada sejengkal tanah dunia.", "3 Pengajaran (Ibrah) Untuk Kita:", "Bahaya Mengubah Sempadan Tanah Dan Hak Jiran: Mengambil harta orang lain, mengalih batu sempadan tanah, atau memakan harta pusaka adik-beradik secara batil membawa ancaman azab yang amat berat di akhirat.", "Ilmu Hadis Menjadi Benteng Daripada Kezaliman: Sa'id bin Zaid RA terpelihara daripada sifat tamak kerana beliau sentiasa mengingati dan mengamalkan hadis yang didengarnya daripada Rasulullah S.A.W.", "Ketenangan Jiwa Lebih Bernilai Daripada Pertelingkahan: Kadangkala mengalah dalam perkara duniawi yang remeh demi mengelakkan sengketa berpanjangan adalah tanda kematangan jiwa orang yang beriman.", "Dalam urusan pembahagian harta keluarga, perniagaan, atau kejiranan, adakah kita benar-benar menjaga sempadan hak orang lain?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1028, "siri": "Sirah-01", "no": 28, "nama": "Abu Ubaidah bin Al-Jarrah", "tajuk": "Saidina Abu Ubaidah bin Al-Jarrah RA — \"Setiap Umat Ada Pemegang Amanah (Al-Amin)\"", "lokasi": "3 Hijrah hingga 9 Hijrah (625 M - 630 M) | Madinah Al-Munawwarah", "ibrah": "Nilai Kepercayaan, Amanah Kerja & Akhlak", "sumber": "Sahih Al-Bukhari 3744", "link": "https://sunnah.com/bukhari:3744", "tema": "Akhlak & Adab", "hook": "Dua batang gigi geraham depannya patah tercabut ketika menggigit keluar mata rantai besi yang terbenam di pipi Rasulullah S.A.W., namun wajahnya tetap digelar wajah paling tampan dan paling amanah!", "body": ["Itulah pengorbanan dan kemuliaan Saidina Abu Ubaidah Amir bin Abdullah bin Al-Jarrah RA dalam sejarah Islam.", "Semasa Perang Uhud (3 Hijrah), topi besi yang dipakai oleh Rasulullah S.A.W. pecah dihentam senjata musuh sehingga dua gelang besi terbenam masuk ke dalam pipi Baginda S.A.W.", "Ketika Saidina Abu Bakar As-Siddiq RA bergegas mahu mencabutnya, Abu Ubaidah bin Al-Jarrah RA merayu dengan bersungguh-sungguh:", "\"Aku mohon kepadamu dengan nama Allah wahai Abu Bakar, biarkanlah aku yang mencabutnya!\"", "Kerana bimbang jika ditarik dengan tangan akan menyakitkan Rasulullah S.A.W., Abu Ubaidah RA menggigit mata rantai besi pertama dengan gigi depannya lalu menariknya perlahan-lahan sehingga besi itu tercabut bersama sebatang gigi depannya!", "Beliau tidak peduli dengan darah yang mengalir di mulutnya, lalu menggigit pula mata rantai besi kedua sehingga tercabut bersama batang gigi depannya yang kedua.", "Ketulusan, kelembutan, dan kejujuran luar biasa yang ada pada diri Abu Ubaidah RA menjadikan beliau begitu istimewa di hati Rasulullah S.A.W.", "Baginda S.A.W. bersabda mengenai beliau di dalam hadis riwayat Anas bin Malik RA di dalam Sahih Al-Bukhari:", "\"Sesungguhnya bagi setiap umat itu ada seorang Amin (pemegang amanah yang paling jujur dan dipercayai), dan sesungguhnya pemegang amanah bagi umat ini ialah Abu Ubaidah bin Al-Jarrah!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Kejujuran Dan Amanah Adalah Jenama Diri Paling Mahal: Di antara ribuan sahabat yang hebat, Abu Ubaidah RA dikenali dengan satu sifat utama yang menjulang namanya: kebolehpercayaan mutlak (Al-Amin).", "Cinta Yang Tulus Melahirkan Kelembutan Tindakan: Walaupun seorang panglima perang yang gagah, Abu Ubaidah RA bertindak dengan penuh cermat dan sanggup mengorbankan giginya sendiri agar Rasulullah S.A.W. tidak merasai kesakitan.", "Kemuliaan Sejati Terletak Pada Pengorbanan, Bukan Rupa Paras: Kehilangan dua gigi depan langsung tidak mencacatkan kehormatan Abu Ubaidah RA, malah menjadi tanda kemuliaan yang dikenang sepanjang zaman.", "Jika rakan sekerja atau pelanggan menyebut nama kita hari ini, adakah kita dikenali sebagai insan yang paling boleh dipercayai?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1029, "siri": "Sirah-01", "no": 29, "nama": "Abu Ubaidah bin Al-Jarrah", "tajuk": "Saidina Abu Ubaidah bin Al-Jarrah RA — Dipilih Menjadi Duta Amanah Buat Penduduk Najran", "lokasi": "9 Hijrah (631 M) | Tahun Delegasi (Amul Wufud), Madinah", "ibrah": "Keadilan, Kompetensi & Reputasi Kejujuran", "sumber": "Sahih Al-Bukhari 4380", "link": "https://sunnah.com/bukhari:4380", "tema": "Akhlak & Adab", "hook": "Ketika para sahabat berharap nama mereka dipilih oleh Rasulullah S.A.W. untuk menerima gelaran \"Lelaki Yang Benar-Benar Jujur\", Baginda memandang ke seluruh majlis lalu memanggil satu nama sahaja!", "body": ["Kisah sahih ini diriwayatkan oleh Hudzaifah bin Al-Yaman RA di dalam kitab Sahih Al-Bukhari.", "Pada tahun ke-9 Hijrah, dua orang pemimpin delegasi dari wilayah Najran (Al-'Aqib dan As-Sayyid) datang menghadap Rasulullah S.A.W. di Madinah.", "Selepas berdialog dengan Baginda S.A.W., mereka bersetuju untuk mengikat perjanjian damai dan menyerahkan bayaran yang ditetapkan kepada kerajaan Islam di Madinah.", "Namun sebelum pulang, mereka mengemukakan satu permintaan penting kepada Rasulullah S.A.W.:", "\"Wahai Muhammad, utuskanlah bersama kami seorang lelaki yang benar-benar jujur dan amanah (Amin), dan janganlah engkau menghantar bersama kami melainkan seorang yang benar-benar boleh dipercayai untuk menguruskan harta serta menjadi hakim jika berlaku pertikaian dalam kalangan kami.\"", "Mendengar permintaan itu, Rasulullah S.A.W. bersabda:", "\"Aku pasti akan mengutuskan bersama kamu seorang lelaki yang benar-benar memegang amanah dengan jujur, sebenar-benar orang yang amanah!\"", "Hudzaifah RA menceritakan bahawa sebaik sahaja mendengar sabda Nabi S.A.W. itu, para sahabat duduk menegakkan badan masing-masing kerana setiap seorang daripada mereka amat berharap terpilih mendapat pengiktirafan tersebut.", "Kemudian Rasulullah S.A.W. bersabda:", "\"Bangunlah wahai Abu Ubaidah bin Al-Jarrah!\"", "Apabila Abu Ubaidah RA berdiri, Rasulullah S.A.W. bersabda kepada utusan Najran dan seluruh sahabat:", "\"Inilah dia pemegang amanah bagi umat ini!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Integriti Adalah Duta Terbaik Bagi Agama: Masyarakat bukan Islam dari Najran menilai keindahan dan keadilan Islam melalui kejujuran wakil yang menguruskan urusan kewangan dan kehakiman mereka.", "Kepercayaan Dibina Melalui Rekod Konsisten: Rasulullah S.A.W. memilih Abu Ubaidah RA tanpa ragu-ragu kerana rekod kejujuran dan akhlaknya yang tidak pernah tercalar sejak memeluk Islam di Makkah.", "Nilai Amanah Lebih Tinggi Daripada Kemahiran Bercakap: Dalam urusan pentadbiran dan kewangan, sifat amanah dan takutkan Allah adalah syarat paling utama sebelum melantik seseorang memegang tanggungjawab.", "Adakah cara kita berurusan dalam perniagaan dan pekerjaan hari ini mencerminkan keindahan akhlak Islam kepada masyarakat sekeliling?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1030, "siri": "Sirah-01", "no": 30, "nama": "Abu Ubaidah bin Al-Jarrah", "tajuk": "Saidina Abu Ubaidah bin Al-Jarrah RA — Keteguhan Di Syam Ketika Wabak Amwas & Dialog Takdir", "lokasi": "18 Hijrah (639 M) | Sempadan Sargh & Bumi Syam (Wabak Taun Amwas)", "ibrah": "Kepimpinan Waktu Krisis, Ikhtiar & Redha Takdir", "sumber": "Sahih Al-Bukhari 5729", "link": "https://sunnah.com/bukhari:5729", "tema": "Kepimpinan & Keberanian", "hook": "\"Adakah engkau mahu lari daripada takdir Allah, wahai Umar?\"", "body": ["Soalan tajam daripada Panglima Besar Syam, Saidina Abu Ubaidah bin Al-Jarrah RA itu dijawab oleh Khalifah Umar bin Al-Khattab RA dengan satu jawapan hikmah yang menjadi kaedah agung memahami konsep usaha dan takdir!", "Kisah bersejarah yang dirakamkan secara panjang lebar oleh Abdullah bin Abbas RA di dalam Sahih Al-Bukhari ini berlaku pada tahun ke-18 Hijrah.", "Ketika itu, Khalifah Umar bin Al-Khattab RA sedang dalam perjalanan menuju ke wilayah Syam.", "Setibanya di kawasan sempadan bernama Sargh, beliau disambut oleh Panglima Tertinggi tentera Islam di Syam iaitu Abu Ubaidah bin Al-Jarrah RA bersama para panglima yang lain.", "Mereka memaklumkan kepada Umar RA bahawa wabak penyakit berjangkit yang dahsyat (Taun Amwas) sedang melanda bumi Syam.", "Selepas bermesyuarat dengan para sahabat Muhajirin dan Ansar, Umar RA mengumumkan keputusan untuk berpatah balik ke Madinah dan tidak membawa rombongannya masuk ke kawasan wabak tersebut.", "Abu Ubaidah RA yang sangat tinggi tawakalnya bertanya kepada Umar RA:", "\"Adakah engkau mahu lari daripada takdir Allah?\"", "Umar RA menjawab dengan penuh hikmah:", "\"Kalaulah orang lain selain engkau yang mengucapkan kata-kata itu wahai Abu Ubaidah! Ya, kita lari daripada satu takdir Allah menuju kepada takdir Allah yang lain!\"", "Tidak lama kemudian, Saidina Abdurrahman bin Auf RA tiba dan menyampaikan hadis Rasulullah S.A.W. tentang SOP kuarantin wabak:", "\"Apabila kamu mendengar wabak melanda sesuatu negeri, janganlah kamu masuk ke dalamnya; dan apabila wabak itu berlaku di negeri tempat kamu berada, maka janganlah kamu keluar melarikan diri daripadanya!\"", "Mendengar hadis itu, Umar RA bersyukur dan pulang ke Madinah, manakala Abu Ubaidah bin Al-Jarrah RA pula taat sepenuhnya kepada hadis tersebut dengan kekal berada di bumi Syam menguruskan tentera dan rakyatnya tanpa melarikan diri, sehinggalah beliau sendiri dijemput Ilahi sebagai syahid wabak Amwas dalam keadaan hidup yang amat zuhud!", "3 Pengajaran (Ibrah) Untuk Kita:", "Mengambil Langkah Pencegahan Adalah Sebahagian Daripada Takdir: Islam mengajar kita bahawa mengelakkan bahaya dan menjaga keselamatan kesihatan bukanlah menolak takdir, tetapi berpindah daripada satu takdir kepada takdir yang lain dengan ikhtiar.", "Pemimpin Sejati Tidak Meninggalkan Pasukan Ketika Krisis: Abu Ubaidah RA kekal bersama tentera dan rakyatnya di Syam mematuhi panduan kuarantin Rasulullah S.A.W. sehingga ke hembusan nafas terakhirnya.", "Kepatuhan Mutlak Kepada Sunnah Menyelesaikan Perselisihan: Sebaik sahaja Abdurrahman bin Auf RA membacakan hadis Rasulullah S.A.W., kedua-dua tokoh agung (Umar RA dan Abu Ubaidah RA) terus tunduk patuh melaksanakan panduan Baginda.", "Dalam menghadapi ujian hidup hari ini, adakah kita menggabungkan ikhtiar yang bijaksana dengan penyerahan hati yang bulat kepada ketetapan Allah?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]}
);
